```cpp
#include <cmath>
#include <cfloat>
#include <algorithm>

class Point2D
{
public:
    float x, y;

    Point2D(float x = 0.0, float y = 0.0)
        : x(x), y(y) {}

    Point2D operator+(const Point2D &other) const {
        return Point2D(x + other.x, y + other.y);
    }

    Point2D operator-(const Point2D &other) const {
        return Point2D(x - other.x, y - other.y);
    }

    Point2D operator*(float scalar) const {
        return Point2D(x * scalar, y * scalar);
    }

    static float distance(const Point2D& point1, const Point2D& point2, const std::string& metric) {
        if(metric == "Euclidean") {
            // Euclidean distance 
            float dx = point2.x - point1.x;
            float dy = point2.y - point1.y;
            return std::sqrt(dx*dx + dy*dy);
        } else if(metric == "Manhattan") {
            // Manhattan distance
            return std::abs(point2.x - point1.x) + std::abs(point2.y - point1.y);
        } else if(metric == "Chebyshev") {
            // Chebyshev distance
            return std::max(std::abs(point2.x - point1.x), std::abs(point2.y - point1.y));
        }
        return FLT_MAX;
    } 
}; 
```

Here, the `+`, `-`, and `*` operators have been overloaded in order to perform pointwise addition, subtraction, and scalar multiplication, respectively. Also, a static member function `distance` has been defined which calculates and returns the distance between two `Point2D` objects according to a specified distance metric.

