Your solution can be achieved using the C++ programming language. In this instance, we are employing a binary search algorithm. It is important to note that a pre-requisite for a binary search is that your array or list needs to be sorted, as it operates by repeatedly dividing in half the portion of the list that could contain the desired value. Here is a basic implementation:

```cpp
#include <iostream>

int binary_search(int arr[], int left, int right, int x)
{
    if (right >= left) {
        int mid = left + (right - left) / 2;

        // If the element is present at the middle
        if (arr[mid] == x)
            return mid;

        // If element is smaller than mid, then it can only be present in left subarray
        if (arr[mid] > x)
            return binary_search(arr, left, mid - 1, x);

        // Else the element can only be present in right subarray
        return binary_search(arr, mid + 1, right, x);
    }

    // We reach here when element is not present in array
    return -1;
}

int main()
{
    int arr[] = { 2, 4, 6, 8, 10};
    int n = sizeof(arr) / sizeof(arr[0]);
    int x = 8;
    int result = binary_search(arr, 0, n - 1, x);

    if(result != -1)
      std::cout<<"Element found at index "<<result;
    else
      std::cout<<"Element not found in array";

    return 0;
}
