            System.out.printf("The Macaulay Duration is: %.2f\n", macaulayDuration);
        }
        catch (Exception e) {
            System.out.println("An exception occurred: " + e.getMessage());
        }
    }

    private static void getInput() {
        System.out.println("Enter the bond's future cash flows: ");
        cashFlow = sc.nextDouble();

        System.out.println("Enter the yield to maturity: ");
        yieldToMaturity = sc.nextDouble();

        System.out.println("Enter the time period to maturity: ");
        time = sc.nextDouble();
    }

    private static double calculateMacaulayDuration(double cashFlow, double yieldToMaturity, double time) {
