In this scenario, we will use a binary search tree and a menu to perform operations like insertion, deletion, searching, and display. A switch-case construct will be used in the main function as a control structure to choose an operation to perform, making more efficient code for the user.

Here is the code below:

```C++
#include <iostream>
using namespace std;

struct Node {
    int key;
    Node* left, *right;
};

// Initializing Node
Node* newNode(int item) {
    Node* temp = new Node;
    temp->key = item;
    temp->left = temp->right = nullptr;
    return temp;
}

// Function to insert in BST
Node* insert(Node* Node, int key) {
    // empty tree
    if (Node == nullptr) return newNode(key);

    // If the tree is not empty
    if (key < Node->key)
        Node->left = insert(Node->left, key);
    else
        Node->right = insert(Node->right, key);

    return Node;
}

// Function to delete in BST
Node* Delete(Node* root, int key) {
    // base condition
    if (root == nullptr)
        return root;

    // searching for the item to be deleted
    if (key < root->key)
        root->left = Delete(root->left, key);
    if (key > root->key)
        root->right = Delete(root->right, key);

    return root;
}

// Function to display BST
void inorderTraversal(Node* root) {
    if (root != nullptr) {
        inorderTraversal(root->left);
        cout << root->key << " ";
        inorderTraversal(root->right);
    }
}

// Main function
int main() {
    Node* root = nullptr;
    int choice, item;

    while (1) {
        cout<<"1.Insertion\n";
        cout<<"2.Deletion\n";
        cout<<"3.Display\n";
        cout<<"4.Quit\n";
        cout<<"Enter your choice : ";
        cin>>choice;

        switch (choice) {
            case 1:
                cout<<"Enter the value to be inserted : ";
                cin>>item;
                root = insert(root, item);
                break;

            case 2:
                cout<<"Enter the value to be deleted : ";
                cin>>item;
                root = Delete(root, item);
                break;

            case 3:
                inorderTraversal(root);
                cout<<endl;
                break;

            case 4:
                return 0;
        }
    }
    return 0;
}
```

This program first creates a binary search tree with the `insert` function. It then offers four choices to the user: insertion, deletion, display, and quit. Depending on the choice user enters, it performs an operation. 'Switch'-'case' is beneficial here because it increases the readability and management of the code and makes it more efficient, as control directly jumps to the respective case without checking all cases sequentially, which happens in 'if'-'else' ladder. The decision process behind using a BST and switch-case construct is the efficient time complexity offered by BST for insertion, deletion, search operations (O(logn)),and by switch-case for decision making(O(1)), that makes the program run in a faster way.

