```python
import json
import logging
import unittest

# Initialize logger
logger = logging.getLogger()

def parse_json(json_string):
    try:
        return json.loads(json_string)
    except json.JSONDecodeError as e:
        logger.error(f'Error decoding JSON: {str(e)}')
        return {}

def extract_info(data, keys=['employee']):
    try:
        for key in keys:
            data = data[key]
        return data
    except KeyError as e:
        logger.error(f'KeyError: {str(e)}')
        return {}

class TestJsonParsing(unittest.TestCase):
    def setUp(self):
        self.json_string = '{"employee":{"name":"John", "department":"Sales", "salary":4000, "details": {"age":30, "city":"New York"}}}'

    def test_parse_json(self):
        data = parse_json(self.json_string)
        self.assertTrue(isinstance(data, dict))
        self.assertTrue('employee' in data)

    def test_extract_info(self):
        data = parse_json(self.json_string)
        employee = extract_info(data)
        self.assertTrue('name' in employee)
        self.assertTrue('details' in employee)

    def test_extract_info_missing_key(self):
        data = parse_json('{}')
        with self.assertLogs(logger, level='ERROR'):
            missing = extract_info(data)
        self.assertEqual(missing, {})

if __name__ == '__main__':
    unittest.main()
```

This script first converts the JSON string to a Python dictionary using the `json.loads` function. The `parse_json` function logs errors if the JSON string is malformed and cannot be converted.

The `extract_info` function is then used to extract information from the nested dictionary. It also handles errors gracefully and logs them if a key is not found in the dictionary.

The script also includes unit tests to verify these functionalities. The tests check that the JSON string is correctly parsed into a dictionary, that the relevant information can be extracted from the dictionary, and that errors won't break the script.

The test case `test_extract_info_missing_key` specifically tests the scenario where an expected key doesn't exist in the dictionary, using the `unittest.TestCase.assertLogs` context manager to assert that an error is logged.

