Here is a JavaScript function that accomplishes the task:

```Javascript
let arr = [1, 2, 2, 3, 4, 4, 5, 5, 5];

function removeDuplicates(arr) {
  let counts = arr.reduce((acc, val) => {
    acc[val] = (acc[val] || 0) + 1;
    return acc;
  }, {});
  return Object.keys(counts).map(key => key * counts[key]);
}

