```python
class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            new_node = Node(data)
            temp = self.head
            while temp.next:
                temp = temp.next
            temp.next = new_node

    def remove_sequential_duplicates(self):
        if not self.head:
            return
        temp = self.head
        data_set = {temp.data.lower()}
        while temp.next:
            if temp.next.data.lower() in data_set:
                temp.next = temp.next.next
            else:
                data_set.add(temp.next.data.lower())
                temp = temp.next

    def print_list(self):
        temp = self.head
        while temp:
            print(temp.data)
            temp = temp.next

def test():
