Here, we'll make use of Python's type checking capabilities via the built-in `type` function and also make use of the respective classes related to the different Data Structures. As creating classes for Linked Lists, Binary Trees etc would be out of scope, let's consider usage of Python's list, dict, tuple and set as corresponding representatives. 

```python
class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Stack:
    def __init__(self):
        self.stack = []

    def push(self, val):
        self.stack.append(val)

class LinkedList:
    def __init__(self, nodes=None):
        self.head = None
        if nodes is not None:
            node = Node(data=nodes.pop(0))
            self.head = node
            while len(nodes) > 0:
                node.next = Node(data=nodes.pop(0))
                node = node.next

class BinaryTree:
    def __init__(self, value):
        self.value = value
        self.left_child = None
        self.right_child = None

class HashMap:
    def __init__(self):
        self.my_dict = {}

def data_structure_identifier(obj):
    data_structure_type = type(obj)
    if data_structure_type == LinkedList:
        return 'LinkedList', 'Scalar', 'LinkedList is a linear data structure in which elements are pointed to the next element by means of a pointer. Each element in a linked list is called a node. A node has two fields: data and a pointer next which points to the next node.'
    elif data_structure_type == BinaryTree:
        return 'BinaryTree', 'Scalar', 'In binary trees, each node can have atmost two children.'
    elif data_structure_type == HashMap:
        return 'HashMap', 'Hash', 'Hashmap stores data in key-value pairs where value accessed by unique key.'
    elif data_structure_type == Stack:
        return 'Stack', 'Array', 'In stack insertion and removal of items takes place from one end called the top of the stack.'
    elif data_structure_type == list:
        return 'List', 'Array', 'Array stores elements in contiguous block of memory. Each element can be identified by an unique index.'
    elif data_structure_type == dict:
        return 'Dictionary', 'Hash', 'Dictionary stores the data in key, value pairs where each unique key maps to a value.'
    elif data_structure_type == tuple:
        return 'Tuple', 'Array', 'Tuple stores multiple elements which are ordered and unchangeable.'
    elif data_structure_type == set:
        return 'Set', 'Hash', 'Set underlies with the implements a hash table, is an unordered collection of items and every element is unique (no duplicates).'
    else:
        return 'Unknown Data Structure', 'Unknown Category'

