```js
function decodeBase64ToJSON(base64String) {
  try {
    // 對輸入壓縮至有效範圍，使其符合Base64編碼規則
    base64String = base64String.replace(/[^A-Za-z0-9+/=]/g, '');

    // 解碼Base64字串
    let text = atob(base64String);

    // 將解碼出來的字串轉換為JSON對象
    let jsonObject = JSON.parse(text);

    // 返回解碼和解析後的JSON對象
    return jsonObject;
  } catch (error) {
    // 捕獲並返回任何可能出現的錯誤
    return error;
  }
}
```

