import java.util.*;

public class Main {
    public static void main(String[] args) {

        Comparator<String> sortByEmbeddedNumber = new Comparator<String>() {
            @Override
            public int compare(String s1, String s2) {
                return extractNumber(s1) - extractNumber(s2);
