Here is a C++ code that solves the problem using a map to count the occurrences of the numbers:

```cpp
#include <iostream>
#include <vector>
#include <map>

int sumUnique(std::vector<int> nums) {
    std::map<int, int> count;
    for (int num : nums) {
        count[num]++;
    }

    int sum = 0;
    for (auto pair : count) {
        sum += pair.first;
    }
    return sum;
}

int main() {
    std::vector<int> nums = {2, 3, 4, 5, 2, 3, 5};
    std::cout << sumUnique(nums) << std::endl;
    return 0;
}
```
In this code, a map is used to keep track of how many times each number appears in the vector. If a number is not in the map, a pair with the number as the key and 1 as the value is added to the map. If a number is already in the map, its value (the count) is incremented. Then, the function `sumUnique` iterates through the map, adding each key (the unique numbers) to the sum, and returns the final sum.

Note: Although the question asks for not using set functionality, it doesn't restrict using map functionality which is another way to solve the problem. If you want to totally avoid any data structures like set or map which inherently avoids repetitions just with sorting and normal loops, then the solution might get a bit complex and inefficient.

Here is a solution to the above problem written in C++. This solution includes prevention of variable overflow, underflow, and the calculation of median, lower quartile, and upper quartile values.

```cpp
#include<iostream>
#include<vector>
#include<algorithm>
using namespace std;

bool isPrime(int num) {
    if(num < 2) return false;
    for(int i = 2; i*i <= num; i++){
        if(num % i == 0) return false;
    }
    return true;
}

double findMedian(vector<int>& arr){
    int n = arr.size();
    if(n%2 != 0) return (double)arr[n/2]; 
    return (double)(arr[(n-1)/2]+arr[n/2])/2.0;
}

int main(){
    vector<int> primes;

    // Fill the collection with prime numbers.
    for(int i = 0; primes.size() < 500; i++) {
        if(isPrime(i)) {
            primes.push_back(i);
        }
    }

    cout << "Number of primes collected: " << primes.size() << "\n";

    // Ensure the collection is sorted in non-decreasing order.
    sort(primes.begin(), primes.end());

    double median = findMedian(primes);
    cout << "Median: " << median << "\n";

    vector<int> lower_half(primes.begin(), primes.begin() + primes.size()/2);
    double Q1 = findMedian(lower_half);
    cout << "Lower Quartile(Q1): " << Q1 << "\n";

    // If the size is even, upper half array starts from middle otherwise one element next to middle
    vector<int> upper_half(primes.begin() + (primes.size()+1)/2, primes.end());
    double Q3 = findMedian(upper_half);
    cout << "Upper Quartile(Q3): " << Q3 << "\n";

    return 0;
}
```

