The following implementation assumes that the input array is sorted. If it isn't, you'll need to sort it before calculating the median and mode.

Here is a C++ code which fulfills your requirements:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <stdexcept>
#include <algorithm>
using namespace std;

vector<int> find_mode(const vector<int>& numbers)
{
    unordered_map<int, int> count;
    int max_count = 0;
    for(int num : numbers) 
    {
        max_count = max(max_count, ++count[num]);
    }

    vector<int> modes;
    for(const auto& kv : count)
    {
        if(kv.second == max_count)
        {
            modes.push_back(kv.first);
        }
    }

    sort(modes.begin(), modes.end());
    return modes;
}

double find_median(vector<int> numbers)
{
    size_t size = numbers.size();

    if (size == 0)
        throw runtime_error("Cannot compute the median of an empty array.");

    if(size % 2 == 0)
        return (numbers[size / 2 - 1] + numbers[size / 2]) / 2.0;
    else
        return numbers[size / 2];
}

double find_average(const vector<int>& numbers)
{
    if(numbers.empty())
        throw runtime_error("Cannot compute the average of an empty array.");

    long sum = 0;  // Using long to prevent overflow.
    for(int num : numbers)
        sum += num;

    return static_cast<double>(sum) / numbers.size();
}

int main()
{
    vector<int> numbers = {1, 2, 2, 3, 4, 5, 5};

    cout << "Sum: " << accumulate(numbers.begin(), numbers.end(), 0) << endl;

    double average = find_average(numbers);
    cout << "Average: " << average << endl;

    double median = find_median(numbers);
    cout << "Median: " << median << endl;

    vector<int> modes = find_mode(numbers);
    cout << "Mode: ";
    for(int mode : modes)
    {
        cout << mode << " ";
    }

    return 0;
}
```

This program calculates the sum of the numbers in the array using `accumulate`, find average and median of the numbers in a sorted array, and computes the mode(s) by finding the number(s) with maximum frequency in the array. 

Also, it performs checks to ensure that the array isn't empty before performing operations that require it to have elements.

If the array isn't sorted, you need to use `std::sort(numbers.begin(), numbers.end());` before finding the median or the mode.

