Since Objective-C is typically known for its use in development for iOS and OS X, you may not be dealing as frequently with data structures in Objective C as you might in other languages. However, the language certainly supports it, and you can implement a ternary tree (a tree where each node has at most 3 children) using the following snippet:

In a typical ternary tree node has a value and three pointers to other nodes. Here's a simple implementation of a node:

```objective-c
@interface TreeNode : NSObject

@property (nonatomic, assign) NSInteger value;
@property (nonatomic, strong) TreeNode *left;
@property (nonatomic, strong) TreeNode *middle;
@property (nonatomic, strong) TreeNode *right;

- (instancetype)initWithValue:(NSInteger)value;

@end

@implementation TreeNode

- (instancetype)initWithValue:(NSInteger)value {
    self = [super init];
    if (self) {
        _value = value;
        _left = nil;
        _middle = nil;
        _right = nil;
    }
    return self;
}

@end
```

This is a basic ternary tree with depth first search functionality:

```objective-c
@interface TernaryTree : NSObject

@property (nonatomic, strong) TreeNode *root;

- (void)insertNodeWithValue:(NSInteger)value;
- (BOOL)findValue:(NSInteger)value;

@end

@implementation TernaryTree

- (void)insertNodeWithValue:(NSInteger)value {
    self.root = [self insertNode:self.root withValue:value];
}

- (TreeNode *)insertNode:(TreeNode *)node withValue:(NSInteger)value {
    if (node == nil) {
        node = [[TreeNode alloc] initWithValue:value];
    } else if (value < node.value) {
        node.left = [self insertNode:node.left withValue:value];
    } else if (value == node.value) {
        node.middle = [self insertNode:node.middle withValue:value];
    } else {
        node.right = [self insertNode:node.right withValue:value];
    }
    return node;
}

- (BOOL)findValue:(NSInteger)value {
    return [self findValue:value inNode:self.root];
}

- (BOOL)findValue:(NSInteger)value inNode:(TreeNode *)node {
    if (node == nil) {
        return NO;
    } else if (value < node.value) {
        return [self findValue:value inNode:node.left];
    } else if (value == node.value) {
        return YES;
    } else {
        return [self findValue:value inNode:node.right];
    }
}

@end
```
In this implementation, `insertNodeWithValue:` is used to add new values to the tree and `findValue:` is then used to perform a depth-first search of the tree for a specific value.

