Here's a simple design of the class hierarchy:

```python
from abc import ABC, abstractmethod

# The abstract base class 'Animal'
class Animal(ABC):
    def __init__(self, species, habitat, diet):
        self._species = species
        self._habitat = habitat
        self._diet = diet

    # Abstract method that needs to be overridden by subclasses
    @abstractmethod
    def sounds(self):
        pass

    # Methods to set and get the attributes
    def set_species(self, species):
        self._species = species

    def get_species(self):
        return self._species

    def set_habitat(self, habitat):
        self._habitat = habitat

    def get_habitat(self):
        return self._habitat

    def set_diet(self, diet):
        self._diet = diet

    def get_diet(self):
        return self._diet

# The 'Mammal' subclass
class Mammal(Animal):
    def __init__(self, species, habitat, diet, fur_color):
        super().__init__(species, habitat, diet)
        self._fur_color = fur_color

    # Overriding the abstract method
    def sounds(self):
        return "Mammal sound"

    # Method to set and get the unique attribute of 'Mammal'
    def set_fur_color(self, fur_color):
        self._fur_color = fur_color

    def get_fur_color(self):
        return self._fur_color

# The 'Bird' subclass
class Bird(Animal):
    def __init__(self, species, habitat, diet, beak_type):
        super().__init__(species, habitat, diet)
        self._beak_type = beak_type

    # Overriding the abstract method
    def sounds(self):
        return "Bird sound"

    # Method to set and get the unique attribute 'beak_type'
    def set_beak_type(self, beak_type):
        self._beak_type = beak_type

    def get_beak_type(self):
        return self._beak_type
```

