Here is a Python function which creates the dictionary as required. It uses a recursive function to build the nested dictionary.

```python
def construct_hierarchical_dict(list_keys, list_vals):
    # Check for list lengths
    if len(list_keys) != len(list_vals):
        raise Exception("Mismatch in lengths of keys and values")

    # Recursive function to build dictionary
    def build_dict(keys, vals):
        if keys and vals:
            return {keys[0]: build_dict(keys[1:], vals[1:])}
        else:
            return {}

    # Build dictionary
    return build_dict(list_keys, list_vals)


# Access values
def access_values(dic, keys):
    # Recursively access nested dictionary
    if keys and keys[0] in dic:
        return access_values(dic[keys[0]], keys[1:])
    # Return value if found at this level
    elif not keys:
        return dic
    # If key is not found, raise KeyError
    else:
        raise KeyError(keys[0])

# Testing the function
list_keys = ["a", "b", "c"]
list_vals = [1, 2, 3]
hierarchical_dict = construct_hierarchical_dict(list_keys, list_vals)
print(hierarchical_dict)  # outputs: {'a': {'b': {'c': {}}}}
print(access_values(hierarchical_dict, ["a", "b", "c"]))  # outputs: {}
```
