We can use the express framework to easily handle our HTTP requests using Node.js. 

Below is a simple implementation of a server that can handle GET, POST, PATCH, and DELETE requests.

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const app = express();
app.use(bodyParser.json());

// In memory storage for the example
let dataStore = {};

app.get('/:key', function(req, res) {
    let key = req.params.key;
    if(dataStore.hasOwnProperty(key))
        res.json({success: true, data: dataStore[key]});
    else
        res.json({success: false, error: 'No data found for the given key.'});
});

app.post('/:key', function(req, res) {
    let key = req.params.key;
    dataStore[key] = req.body;
    res.json({success: true, data: dataStore[key]});
});

app.patch('/:key', function(req, res) {
    let key = req.params.key;
    if(dataStore.hasOwnProperty(key)){
        dataStore[key] = {...dataStore[key], ...req.body};
        res.json({success: true, data: dataStore[key]});
    } else
        res.json({success: false, error: 'No data found for the given key.'});
});

app.delete('/:key', function(req, res) {
    let key = req.params.key;
    if(dataStore.hasOwnProperty(key)) {
        delete dataStore[key];
        res.json({success: true});
    } else
        res.json({success: false, error: 'No data found for the given key.'});
});

app.listen(3000, function() {
    console.log('Server is listening on port 3000');
});
```

This will start a server on localhost:3000. You can perform GET, POST, PATCH, and DELETE requests to localhost:3000/key with JSON request bodies for POST and PATCH. 

