**1. Function One (RGB to HSV Conversion):**

```python 
def rgb_to_hsv(r, g, b):
    try:
        r, g, b = r/255.0, g/255.0, b/255.0

        mx = max(r, g, b)
        mn = min(r, g, b)
        df = mx-mn

        if mx == mn:
            h = 0
        elif mx == r:
            h = (60 * ((g-b)/df) + 360) % 360
        elif mx == g:
            h = (60 * ((b-r)/df) + 120) % 360
        elif mx == b:
            h = (60 * ((r-g)/df) + 240) % 360

        if mx == 0:
            s = 0
        else:
            s = (df/mx)*100

        v = mx*100

        return h, s, v

    except ZeroDivisionError:
        print("Error: Zero Division not possible")

    except:
        print("Error: Invalid operation")
```

**2. Function Two (HSV to RGB Conversion):**

```python 
def hsv_to_rgb(h, s, v):
    try:
        s = s / 100
        v = v / 100
        hi = int((h / 60) % 6)
        f = (h / 60) - (h / 60).floor()
        p = v * (1 - s)
        q = v * (1 - f * s)
        t = v * (1 - (1 - f) * s)

        if hi == 0: 
            r, g, b = v, t, p
        elif hi == 1:
            r, g, b = q, v, p
        elif hi == 2: 
            r, g, b = p, v, t
        elif hi == 3:
            r, g, b = p, q, v
        elif hi == 4: 
            r, g, b = t, p, v
        elif hi == 5:
            r, g, b = v, p, q

        r, g, b = round(r * 255), round(g * 255), round(b * 255)

        return r, g, b

    except ZeroDivisionError:
        print("Error: Zero Division not possible")

    except:
        print("Error: Invalid operation")
``` 

