Here is a C++ implementation of the Quaternion class using floats and mentioning all the methods you asked for. However, beware this does not contain full error checking or handling for edge cases.

```cpp
#include <cmath>
#include <iostream>

class Quaternion{
private:
    float x, y, z, w;
public:
    Quaternion(float w=1.0, float x=0.0, float y=0.0, float z=0.0)
    : w(w), x(x), y(y), z(z){}

    Quaternion operator+(const Quaternion& q) const {
        return Quaternion(w + q.w, x + q.x, y + q.y, z + q.z);
    }

    Quaternion operator-(const Quaternion& q) const {
        return Quaternion(w - q.w, x - q.x, y - q.y, z - q.z);
    }

    Quaternion operator*(const Quaternion& qr) const {
        return Quaternion(
            w * qr.w - x * qr.x - y * qr.y - z * qr.z,  // new w-amplitude
            w * qr.x + x * qr.w + y * qr.z - z * qr.y,  // new x-amplitude
            w * qr.y + y * qr.w + z * qr.x - x * qr.z,  // new y-amplitude
            w * qr.z + z * qr.w + x * qr.y - y * qr.x); // new z-amplitude
    }

    void normalize(){
        float norm = std::sqrt(w * w + x * x + y * y + z * z);
        if(norm > 0.0){
            w /= norm;
            x /= norm;
            y /= norm;
            z /= norm;
        }
    }

    Quaternion inverse() const {
        return Quaternion(w, -x, -y, -z);
    }

    // Convenience method for printing
    void printQuaternion(){
        std::cout << "[" << w << ", " << x << ", " << y << ", " << z << "]\n";
    }

    // Methods for quaternion to rotation matrix and Euler angles 
    // are left as an exercise (they involve more complex mathematics).
};

int main(){
    Quaternion q1(1.0, 2.0, 3.0, 4.0), q2(1.0, -2.0, -3.0, -4.0);
    Quaternion result = q1 + q2;
    result.printQuaternion();
    result = q1 - q2;
    result.printQuaternion();
    result = q1 * q2;
    result.printQuaternion();
    result.normalize();
    result.printQuaternion();
    Quaternion inv = result.inverse();
    inv.printQuaternion();
    return 0;
}
```
In this script, `printQuaternion()` is a method used for convenience to print the quaternion to the console. The methods for transforming a quaternion into a rotation matrix and obtaining Euler angles from a quaternion are not implemented here because they involve significantly more math.

