```csharp
public static bool IsArmstrongNumber(int number)
{
    // Convert the number to a string to easily get the length
    string digits = number.ToString();
    int length = digits.Length;

    int sum = 0;
    foreach (char digit in digits)
    {
        // Convert the digit back to an int and raise it to the power of length
        int digitValue = int.Parse(digit.ToString());
        sum += (int)Math.Pow(digitValue, length);
    }

    // If the sum equals the original number, then it is an Armstrong number
    return sum == number;
}
```

