{
    public static void Main()
    {
        int[][] numbers = {new []{2, 3, 5, 7}, new []{6, 8, 10, 12}, new []{14, 15, 17, 19}}; 

        var result = numbers
            .SelectMany(innerArray => innerArray)  // Flatten the 2-dimensional array into a 1-dimensional sequence
            .Where(x => x % 2 == 0)  // Filter only for even numbers
            .Select(x => x * x)  // Calculate squares of numbers
            .Sum();  // Calculate the sum of squares

