You can use the sort function in JavaScript to sort an array of objects based on a specific property. Here's a flexible function that takes in an array of objects and a property to sort by:

```javascript
function sortObjectsArray(array, property) {
    return array.sort(function(a, b) {
        if (a[property] < b[property]) {
            return -1;
        }
        else if (a[property] > b[property]) {
            return 1;
        }
        return 0;
    });
}

// usage
let arr = [{name: 'Anna', age: 25}, {name: 'Ben', age: 18}, {name: 'Charles', age: 20}];
console.log(sortObjectsArray(arr, 'age'));
