Here's a JavaScript function that extracts all hyperlinks from a given text and categorizes them as internal or external. This function uses a regular expression for hyperlink extraction and URL parsing to check whether the link is internal or external. For validating external links, it uses "fetch" API. 

Please note, node.js environment doesn't support fetch API natively. You would need to install 'node-fetch' package (`npm install node-fetch`) if you are running this script in node.js environment.

Lastly, due to Cross Origin policy, we may not able to check the status of any website from the browser console that is not in our control. The script will throw CORS error.

```javascript
const fetch = require('node-fetch');

// Function to solve the problem
async function solve(text, domain) {
    // Regular expression to match URLs
    const regex = /(https?:\/\/[^\s]+)/g;

    let match;
    let result = {
        internal: [],
        external: []
    };

    // Find matches
    while ((match = regex.exec(text)) !== null) {
        // Check whether the link is internal or external
        const url = new URL(match[0]);
        if (url.hostname === domain) 
            result.internal.push(url.href);
        else {
            result.external.push(url.href);

            // Validate if the external link is active
            // Uncomment below lines to check the status of the URLs 
            // We have commented it due to CORS issue.
            /*
            try {
                let response = await fetch(url.href);
                console.log(`Status of ${url.href}: ${response.status}`);
            } catch(error) {
                console.log(`Failed to fetch ${url.href}: ${error}`);
            }
            */
        }
    }

    // Return the result
    return result;
}

