```c++
#include<iostream>
using namespace std;

class Node
{
public:
    int data;
    Node* next;
    Node* prev;
};

class DoublyLinkedList
{
private:
    Node* head;
public:
    DoublyLinkedList()
    {
        head = NULL;
    }
    void insert(int value)
    {
        Node* temp = new Node();
        temp->data = value;
        temp->next = NULL;
        temp->prev = NULL;

        if(head == NULL)
        {
            head = temp;
        }
        else
        {
            Node* last = head;
            while(last->next != NULL)
            {
                last = last->next;
            }
            last->next = temp;
            temp->prev = last;
        }
    }

    void display()
    {
        Node* temp = head;
        while(temp != NULL)
        {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }
};

