Creating a function to authenticate emptiness of a dictionary, list, tuple and set, including any nested counterparts:

```python
def authenticate_empty_entities(entity, _visited=None):
    if _visited is None:
        _visited = set()  # Keep track of visited entities to prevent circular references

    if id(entity) in _visited:  # If the entity was already visited, it's a circular reference
        return True, 0

    _visited.add(id(entity))  # Mark this entity as visited

    if isinstance(entity, dict):
        if len(entity) == 0:
            return True, 1  # Return True to signal emptiness, and 1 to increment count of empty entities

        for key, value in entity.items():
            key_is_empty, key_count = authenticate_empty_entities(key, _visited)
            value_is_empty, value_count = authenticate_empty_entities(value, _visited)

            if not key_is_empty or not value_is_empty:  # If either key or value is not empty
                return False, key_count + value_count  # Dictionary is not empty, return False and current count

        return True, key_count + value_count + 1  # Increment count because entire dict is empty

    elif isinstance(entity, (list, tuple, set)):  
        if len(entity) == 0:
            return True, 1 

        for item in entity:
            item_is_empty, item_count = authenticate_empty_entities(item, _visited)

            if not item_is_empty:  # If item is not empty
                return False, item_count  # Entity is not empty, return False and current count

        return True, item_count + 1  # Increment count because entire entity is empty

    else:
        return False, 0  # For non-iterable entities, return False (non-empty) and don't increment count
```

