```C++
#include <iostream>

int main()
{
    // Initialize two numerical values
    int num1 = 15, num2 = 25;   

    // Declare pointers for the above values
    int *ptr1 = &num1, *ptr2 = &num2;   

    // Calculate the aggregate using pointer variables
    int aggregate = *ptr1 + *ptr2;  

    // Print the aggregate
    std::cout << "The aggregate of " << num1 << " and " << num2 << " is: " << aggregate;

    return 0;
}
