Here's a simple Python solution that utilizes recursion for handling nested lists:

```python
def flatten_list(nested_list):
    for i in nested_list:
        if isinstance(i, list):
            for j in flatten_list(i):
                yield j
        else:
            yield i

def group_elements(lst):
    flat_list = list(flatten_list(lst))
    return {i: flat_list.count(i) for i in flat_list}

# Example usage:
lst = [1, 2, 2, 2, 3, 3, 4, 4, 5, [1, 2, 3]]
print(group_elements(lst))
```

The `flatten_list` function is a generator function that recursively flattens the list. The `group_elements` function counts the number of occurrences of each element in the flattened list and returns a dictionary.

Please note, this code could be problematic for large nested lists due to the time complexity of the count() method. In that case, a more efficient solution would be to use a dictionary to keep track of counts as we flatten the list. This can be achieved as follows:

```python
def flatten_and_count(nested_list, count_dict=None):
    if count_dict is None:
        count_dict = {}

    for item in nested_list:
        if isinstance(item, list):
            flatten_and_count(item, count_dict)
        else:
            if item in count_dict:
                count_dict[item] += 1
            else:
                count_dict[item] = 1
    return count_dict

# Example usage:
lst = [1, 2, 2, 2, 3, 3, 4, 4, 5, [1, 2, 3]]
print(flatten_and_count(lst))
```

Here is a simple implementation of a binary search tree sort in Rust:

```rust
struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

impl Node {
    fn new(value: i32) -> Node {
        Node { value, left: None, right: None }
    }

    fn insert(&mut self, new_val: i32) {
        if self.value < new_val {
            if let Some(right) = &mut self.right {
                right.insert(new_val);
            } else {
                self.right = Some(Box::new(Node::new(new_val)));
            }
        } else {
            if let Some(left) = &mut self.left {
                left.insert(new_val);
            } else {
                self.left = Some(Box::new(Node::new(new_val)));
            }
        }
    }

    fn in_order_traversal(&self, callback: &mut dyn FnMut(i32)) -> () {
        if let Some(left) = &self.left { 
            left.in_order_traversal(callback);
        }

        callback(self.value);

        if let Some(right) = &self.right { 
            right.in_order_traversal(callback);
        }
    }

}

fn tree_sort(nums: Vec<i32>) -> Vec<i32> {
    let mut root = Node::new(nums[0]);

    for &num in nums[1..].iter() {
        root.insert(num);
    }

    let mut sorted_nums = vec![];
    root.in_order_traversal(&mut |n| sorted_nums.push(n));
    sorted_nums
}

fn main() {
    let nums = vec![5, 2, 3, 4, 1];
    let sorted_nums = tree_sort(nums);

    println!("{:?}", sorted_nums); // prints: [1, 2, 3, 4, 5]
}
```

