Let's start with the code for generating the Fibonacci Series using Multi-threading approach:

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

std::vector<uint64_t> fibSeries;
std::mutex mtx;

void calculateFib(int n) {
   uint64_t t1 = 0, t2 = 1, nextTerm = 0;

   for (int i = 1; i <= n; ++i) {
      if(i == 1) {
          nextTerm = t1;
      } else if(i == 2) {
          nextTerm = t2;
      } else {
          nextTerm = t1 + t2;
          t1 = t2;
          t2 = nextTerm;
      }

      std::lock_guard<std::mutex> lock(mtx);
      fibSeries.push_back(nextTerm);
   }
}

int main() {
    int n = 100; // Fibonacci series up to 100 elements
    fibSeries.reserve(n); // Reserve space for efficiency

    std::thread t1(calculateFib, n/2);
    std::thread t2(calculateFib, n/2);

    t1.join();
    t2.join();

    for (const auto &val : fibSeries) {
        std::cout << val << " ";
    }

    return 0;
}
```

Note that in this code, we have used `lock_guard` to handle the mutual exclusion on the shared `fibSeries` vector.

Also, in order to perform a performance analysis, you should use a high-resolution timer to measure the time it takes for the program to complete with both the single-threaded and the multi-threaded versions. Here are references to do that:

- <https://en.cppreference.com/w/cpp/chrono>
- <https://en.cppreference.com/w/cpp/chrono/high_resolution_clock/now>

Please note: Given code will not create a proper sequence as the order of execution is not guaranteed in multi-threading and that's the reason Fibonacci series and multi-threading are not the best match. Two threads are calculating half the series respectively but they might not deposit the calculated value in order which will lead to an incorrect series. Fibonacci series calculation is a sequential process and trying to parallelize it is not efficient or correct in this context.

The following Python code implements a doubly-linked list and a method of using the list data elements to create a dictionary with each item's frequency of occurrence.

```Python
class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        if self.head is None:
            self.head = Node(data)
        else:
            curr_node = self.head
            while curr_node.next:
                curr_node = curr_node.next
            new_node = Node(data)
            curr_node.next = new_node
            new_node.prev = curr_node

    def insert(self, data, position):
        new_node = Node(data)
        if position == 0:
            new_node.next = self.head
            if self.head:
                self.head.prev = new_node
            self.head = new_node
        else:
            curr_node = self.head
            for _ in range(position - 1):
                if curr_node is None:
                    return
                curr_node = curr_node.next
            new_node.next = curr_node.next
            if curr_node.next:
                curr_node.next.prev = new_node
            curr_node.next = new_node
            new_node.prev = curr_node

    def delete(self, position):
        if self.head is None:
            return
        curr_node = self.head
        for _ in range(position):
            if curr_node is None:
                return
            curr_node = curr_node.next
        if curr_node.prev:
            curr_node.prev.next = curr_node.next
        if curr_node.next:
            curr_node.next.prev = curr_node.prev
        if curr_node == self.head:
            self.head = curr_node.next
        curr_node = None

    def lexical_frequency(self):
        lexical_dict = {}
        curr_node = self.head
        while curr_node:
            lexical_item = curr_node.data
            if lexical_item in lexical_dict:
                lexical_dict[lexical_item] += 1
            else:
                lexical_dict[lexical_item] = 1
            curr_node = curr_node.next
        return lexical_dict

