Here's the corrected code:

```python
def count_rotations(nums):
    # Check if the array is sorted in descending order
    if nums[0] >= nums[-1]:
        max_index = 0
        # Find the index of the max value 
        for i in range(1, len(nums)):
            if nums[i] >= nums[max_index]:
                max_index = i
        # If the array is not sorted, return -1
        if max_index == len(nums) - 1 and nums[0] < nums[1]:
            return -1
        else:
            # If sorted in descending order, return index of max value + 1
            return max_index + 1
    else:
        min_index = 0
        # Find the index of the min value
        for i in range(1, len(nums)):
            if nums[i] <= nums[min_index]:
                min_index = i
        # If the array is not sorted, return -1
        if min_index == len(nums) - 1 and nums[0] > nums[1]:
            return -1
        else:
            # If sorted in ascending order, return index of min value
            return min_index
```
