import numpy as np

# Batch conversion
def rgb_to_hsv_batch(rgb_list):
    # Assuming input is a list of tuples
    return [rgb_to_hsv(tuple(x)) for x in rgb_list]

def hsv_to_rgb_batch(hsv_list):
    # Assuming input is a list of tuples
    return [hsv_to_rgb(tuple(x)) for x in hsv_list]

# Validation
assert rgb_to_hsv_batch([(255, 0, 0), (0, 255, 0), (0, 0, 255)]) == [(0, 1, 1), (120, 1, 1), (240, 1, 1)]
