Here is a JavaScript implementation of the data structure you described. This structure uses a PriorityQueue to manage tasks using three strategies—FIFO, LIFO, and Priorities. 

Tasks are time-stamped and ordered using a priority strategy by default. But, this can be changed using the setStrategy() function. The average waiting time is based on the time between the task creation and removal.

Note: This example use "binary-heap-js" npm package, please install the npm package first,

```javascript
const MinHeap = require('binary-heap-js').MinHeap;

class Task {
  constructor(name, priority) {
    this.name = name;
    this.priority = priority;
    this.timestamp = Date.now();
  }
}

class PriorityQueue {
  constructor() {
    this.tasks = new MinHeap((a, b) => this.strategy(a, b));
    this.totalWaitTime = 0;
    this.totalTasks = 0;
    this.strategy = this.priorityStrategy; // Default strategy
  }

  addTask(name, priority) {
    const task = new Task(name, priority);
    this.tasks.insert(task);
  }

  removeTask() {
    const task = this.tasks.extractRoot();
    this.totalWaitTime += Date.now() - task.timestamp;
    this.totalTasks++;
    return task;      
  }

  setStrategy(strategyName) {
    if(strategyName === 'FIFO') this.strategy = this.fifoStrategy;
    else if(strategyName === 'LIFO') this.strategy = this.lifoStrategy;
    else this.strategy = this.priorityStrategy;
    this.tasks = new MinHeap((a, b) => this.strategy(a, b));
  }

  fifoStrategy(a, b) {
    if(a.timestamp < b.timestamp) return -1;
    if(a.timestamp > b.timestamp) return 1;
    return 0;
  }

  lifoStrategy(a, b) {
    if(a.timestamp > b.timestamp) return -1;
    if(a.timestamp < b.timestamp) return 1;
    return 0;
  }

  priorityStrategy(a, b) {
    if(a.priority < b.priority) return -1;
    if(a.priority > b.priority) return 1;
    if(a.timestamp < b.timestamp) return -1;
    if(a.timestamp > b.timestamp) return 1;
    return 0;
  }

  getAverageWaitTime() {
    if(this.totalTasks === 0) return 0;
    return (this.totalWaitTime / this.totalTasks) / 1000; // In seconds
  }

  searchTasks(keyword) {
    return this.tasks.getArray().filter((task) => task.name.includes(keyword));
  }

  [Symbol.iterator]() {
    let index = -1;
    let data = this.tasks.getArray();

    return {
      next: () => ({ value: data[++index], done: !(index in data) })
    };
  }
}
```

Tip: The time complexity for priority based queue operations (insert and remove) tend to be logarithmic (O(log(n))), while the search operation could be linear (O(n)). The space complexity is linear (O(n)), as each task requires a constant amount of space. To optimize space further more, one may consider storing the common task properties (like due dates, project IDs, etc.) in a separate location and keep only the references inside tasks. But, this could complicate the code without a significant improvement in efficiency.

