    public static Map<Integer, Integer> findMaxThree(int[] array) {
        Map<Integer, Integer> map = new HashMap<>();
        int first = Integer.MIN_VALUE, second = Integer.MIN_VALUE, third = Integer.MIN_VALUE;
        int firstIdx = -1, secondIdx = -1, thirdIdx = -1;

        for (int i = 0; i < array.length; i++) {
            if (array[i] > first) {
                third = second;
                second = first;
                first = array[i];
                thirdIdx = secondIdx;
                secondIdx = firstIdx;
                firstIdx = i;
            } else if (array[i] > second) {
                third = second;
                second = array[i];
                thirdIdx = secondIdx;
                secondIdx = i;
            } else if (array[i] > third) {
                third = array[i];
                thirdIdx = i;
            }
        }

        if (firstIdx != -1) map.put(firstIdx, first);
        if (secondIdx != -1) map.put(secondIdx, second);
        if (thirdIdx != -1) map.put(thirdIdx, third);

        return map;
    }
}
```

