```js
function rotateAlphabet(character, shift) {
    let charCode = character.charCodeAt(0) - 65; //ASCII value of 'A' is 65
    charCode = (charCode + shift) % 26; //perform shift and wrap around if beyond 'Z'
    return String.fromCharCode(charCode + 65); //convert back to character
}

function decode(message, key) {
    //validate input
    if(!/^[A-Z\s]+$/.test(message)) {
        console.log("Error: The message should only contain uppercase letters and spaces!");
        return;
    }
    if(!Number.isInteger(key) || key < 1) {
        console.log("Error: The key should be a positive integer!");
        return;
    }

    let decrypted = '';
    for(let i = 0; i < message.length; i++){
        if(message[i] === ' ') {  //If space, then append to decrypted message
           decrypted += ' ';
        }
        else {
           decrypted += rotateAlphabet(message[i], key);  //Caesar cipher decryption
        }
    }

    let final = '';
    for(let i = 0; i < decrypted.length; i++){
        if(decrypted[i] === ' ') {  //If space, then append to final message
           final += ' ';
        }
        else {
          final += rotateAlphabet(decrypted[i], 13);  //ROT13 cipher decryption
        }
    }

    console.log(final);
}

//example usage
decode("N WNTTJW YJXY", 10);
```

This script first defines a helper function `rotateAlphabet()` that performs the rotation of a single character by a certain number of positions. Then the `decode()` function validates the input, applies the Caesar cipher method to each character of the message (ignoring spaces), applies the ROT13 cipher method to the decrypted message, and finally logs the decoded message to the console.

For example, calling `decode("N WNTTJW YJXY", 10);` will output "A SIMPLE TEST".

