```python
class Node:
    def __init__(self, word):
        self.word = word
        self.next = None
        self.prev = None


class CircularDoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, word):
        if not self.head:
            self.head = Node(word)
            self.head.next = self.head
            self.head.prev = self.head
        else:
