```python
import json

class Node:
    def __init__(self, title, rating):
        self.title = title
        self.rating = rating
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, title, rating):
        if not self.root:
            self.root = Node(title, rating)
        else:
            self._insert(self.root, title, rating)

    def _insert(self, node, title, rating):
        if rating < node.rating:
            if node.left:
                self._insert(node.left, title, rating)
            else:
                node.left = Node(title, rating)
        else:
            if node.right:
                self._insert(node.right, title, rating)
            else:
                node.right = Node(title, rating)

    def inorder(self, node):
        if node:
            self.inorder(node.left)
            print(node.rating)
            self.inorder(node.right)


if __name__ == "__main__":
