This can be solved by using a common problem solving technique in programming, called recursion. The logic goes like this: we recursively merge the lists by selecting the smaller value at the head of each list at each step. Here's a simple C++ code that does just that:

```cpp
#include<bits/stdc++.h> 
using namespace std; 

//Node Structure
class Node 
{ 
    public:
    int data; 
    Node* next; 
};

//Merge Function
Node* SortedMerge(Node* a, Node* b) 
{ 
    Node* result = NULL; 

    /* At this stage, the base cases to handle are when either 
      of the lists is empty, i.e., we just return the remaining 
      non-empty list */
    if (a == NULL) 
        return(b); 
    else if (b==NULL) 
        return(a); 

    /* If 'a' is smaller, then result points to 'a' and then 
      we recursively merge the remaining lists */
    if(a->data <= b->data) 
    { 
        result = a; 
        result->next = SortedMerge(a->next, b); 
    } 
    /* If data of 'b' is smaller, then result points to 'b' 
     and we recursively merge the remaining lists */
    else
    { 
        result = b; 
        result->next = SortedMerge(a, b->next); 
    } 

    return(result); 
} 

//Function to create a new node
Node* newNode(int data) 
{ 
    Node* new_node = (Node*) malloc(sizeof(Node)); //create a new node
    new_node->data = data; 
    new_node->next = NULL; 
    return new_node; 
} 

// Function to print linked list 
void printList(Node *node) 
{ 
    while (node!=NULL) //traverse list to play all elements
    { 
        printf("%d ", node->data); 
        node = node->next; 
    } 
} 

//Driver code
int main() 
{ 
    Node* res = NULL; 
    Node* a = NULL; 
    Node* b = NULL; 

    a = newNode(5); 
    a->next = newNode(10); 
    a->next->next = newNode(15); 

    b = newNode(2); 
    b->next = newNode(3); 
    b->next->next = newNode(20); 

    res = SortedMerge(a, b); 

    printf("Merged Linked List is: \n"); 
    printList(res); 

    return 0; 
} 
```
This given code merges two linked lists in a sorted manner. The SortedMerge() function is used to merge both linked lists. The result obtained is a pointer to a dummy node instead of call by reference. Merges the given linked lists and returns the head of the merged list does not change the previous lists. Thus, this function merges two sorted linked lists.

