    } else {
        const vowels = ['a', 'e', 'i', 'o', 'u'];
        let vowelCount = {};
        let count = 0;

        vowels.forEach(vowel => {
            const matches = str.match(new RegExp(vowel, 'gi'));
            if(matches){
                count += matches.length;
                vowelCount[vowel] = matches.length;
            }
        });

        if(count === 0){
            return "Error: The string does not contain any vowels.";
        } else {
            return vowelCount;
        }
    }
}
```
