```python
import os
import xml.etree.ElementTree as ET
import subprocess
import hashlib

def create_pkgdict():
    """Create a dictionary for fast path lookup from /data/system/packages.xml."""
    pkgdict = {}
    tree = ET.parse('/data/system/packages.xml')
    for element in tree.iter('package'):
        pkgdict[element.attrib['name']] = element.attrib['path']
    return pkgdict


def list_installed_pkgs(args):
    """Lists the members of a given category of packages."""
    if 'priv-app' in args.category:
        category = '/system/priv-app'
    else:
        category = '/system/app'

    return [package for package in os.listdir(category) if package.endswith('.apk')]


def list_installed_pkgs_nougat(args):
    """Uses Nougat's cmd command to query the package service (faster)."""
    return subprocess.check_output('cmd package list packages').splitlines()


def check_substratum(nougat):
    """Checks if the Substratum engine is installed."""
    if nougat:
        return 'projekt.substratum' in list_installed_pkgs_nougat()
    else:
        return 'projekt.substratum' in list_installed_pkgs()


def exclude_overlays(aapt, pkgdict, pkgs):
    """Excludes Substratum overlays from the packages to extract."""
    return [pkg for pkg in pkgs if aapt('%s/%s' % (pkgdict[pkg], pkg)) != 'SubstratumOverlay']


def exclude_arcus_variants(pkgs):
    """Excludes Arcus theme variants from the packages to extract."""
    return [pkg for pkg in pkgs if 'arcus.' not in pkg]


def check_already_extracted(pkgpath, md5sums):
    """Checks if an APK has already been extracted."""
    with open(pkgpath, 'rb') as f:
        apk_md5 = hashlib.md5(f.read()).hexdigest()
    return apk_md5 in md5sums
```

Please note that you may need to adjust paths or package names to suit your specific Android setup. Furthermore, ensure that you have the necessary permissions to access `/data/system/packages.xml` and other system paths.

