def check_prime(n):
    if n <= 1:
        return 'composite'
    elif n <= 3:
        return 'prime'
    elif n % 2 == 0 or n % 3 == 0:
        return 'composite'
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return 'composite'
        i += 6
    return 'prime'

