Here's a script that achieves the desired tasks using MongoDB Aggregation Framework:

```javascript
const { MongoClient } = require('mongodb');

const uri = 'mongodb+srv://<username>:<password>@cluster.mongodb.net/database_name?retryWrites=true&w=majority';
const client = new MongoClient(uri, { useNewUrlParser: true, useUnifiedTopology: true });

async function main() {
  try {
    await client.connect();

    const date1 = new Date('<date1>');
    const date2 = new Date('<date2>');
    const salesDate1 = new Date('<sales_date1>');
    const salesDate2 = new Date('<sales_date2>');

    const result = await client
      .db('database_name')
      .collection('users')
      .aggregate([
        {
          $match: {
            registration_date: {
              $gte: date1,
              $lte: date2,
            },
          },
        },
        {
          $lookup: {
            from: 'sales',
            let: { id: '$_id' },
            pipeline: [
              {
                $match: {
                  $expr: { $eq: ['$user_id', '$$id'] },
                  date: {
                    $gte: salesDate1,
                    $lte: salesDate2,
                  },
                },
              },
              {
                $group: {
                  _id: '$user_id',
                  total_products: { $sum: 1 },
                },
              },
            ],
            as: 'sales',
          },
        },
        {
          $lookup: {
            from: 'reviews',
            let: { id: '$_id' },
            pipeline: [
              {
                $match: {
                  $expr: { $eq: ['$user_id', '$$id'] },
                },
              },
              {
                $group: {
                  _id: '$user_id',
                  average_rating: { $avg: '$rating' },
                },
              },
            ],
            as: 'reviews',
          },
        },
        {
          $addFields: {
            total_products: { $arrayElemAt: ['$sales.total_products', 0] },
            average_rating: { $arrayElemAt: ['$reviews.average_rating', 0] },
          },
        },
        {
          $project: {
            _id: 1,
            username: 1,
            registration_date: 1,
            total_products: 1,
            average_rating: 1,
            sales: 0,
            reviews: 0,
          },
        },
        {
          $sort: { total_products: -1 },
        },
      ])
      .toArray();

    console.log(result);
  } finally {
    client.close();
  }
}

main().catch(console.error);
```

Replace `<username>`, `<password>`, `database_name`, `<date1>, <date2>`, and `<sales_date1>, <sales_date2>` with the appropriate values.

