    min, sec = divmod(sec, 60)
    hours, min = divmod(min, 60)
    days, hours = divmod(hours, 24)

    if format == 'HH:MM:SS':
        return "{:02d}:{:02d}:{:02d}".format(int(hours), int(min), int(sec))
    elif format == 'HH hours MM minutes SS seconds':
        return "{} hours {} minutes {} seconds".format(int(hours), int(min), int(sec))
    elif format == 'D days HH hours MM minutes and SS seconds':
        return "{} days {} hours {} minutes and {} seconds".format(int(days), int(hours), int(min), int(sec))
