    class Program
    {
        static void Main(string[] args)
        {
            int n = 50;
            Console.WriteLine(PrimeProduct(n));
        }

        static long PrimeProduct(int n)
        {
            if(n == 1)
                return 1;

            if(IsPrime(n))
                return n * PrimeProduct(n - 1);

            return PrimeProduct(n - 1);
