function changeImageStyle() {
    const imageNodes = document.querySelectorAll('img');

    imageNodes.forEach(function(node) {
        if (node.classList.contains('material')) {
            // Apply CSS styling to the 'material' class elements
            node.style.border = '5px solid red';
        }
    });

    var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
            if (mutation.addedNodes) {
                mutation.addedNodes.forEach(function(node) {
                    if (node.nodeType === 1 && node.tagName === 'IMG') {
