def check_prime(n):
    """
    Checks if a number is prime.
    """
    if n == 1:
        return False
    elif n == 2:
        return True
    else:
        for i in range(2, n):
            if n % i == 0:
                return False
        return True	

def calculate_sum(n):
    """
    Calculates the sum of the reciprocals of all prime numbers up to and including n.
    """
    total = 0
    for i in range(2, n + 1):
        if check_prime(i):
            total += 1/i
    return total

n = int(input("Please input a positive integer: "))
print("The sum of the reciprocals of all prime numbers up to", n, "is", calculate_sum(n))
```

