function bubbleSort(arr) {
    let len = arr.length;
    let swapped;
    let swapCount = 0;
    do {
        swapped = false;
        for (let i = 0; i < len; i++) {
            if (arr[i] > arr[i + 1]) {
                let tmp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = tmp;
                swapped = true;
                swapCount++;
            }
        }
    } while (swapped);
    return swapCount;
}

