Here is a basic concept of a program in C++ to implement a queue and clear operation.

C++ provides queue data structure as a part of standard template library (STL). The operations on queue like push (insert in the first) and pop (remove from the first) that have time complexity of O(1).

However, clearing the queue seems to take linear time with current stl implementation as we are popping the elements out one by one.

```cpp
#include<iostream>
#include<queue>
#include<cstdlib>
#include<ctime>
using namespace std;

int main() {
    srand(time(0));
    queue <int> q;
    int n = rand() % 100;

    // Enqueue operation
    for(int i = 0; i < n; i++) {
        q.push(rand() % 1000);
    }

    // Check if queue is empty
    if(q.empty()) {
        cout << "Queue is empty." << endl;
        return 1;
    } else {
        cout << "Queue is not empty. Proceeding for clearing queue." << endl;
    }

    clock_t begin = clock();

    // Clearing the queue using pop operation
    while(!q.empty()) {
        q.pop();
    }
    clock_t end = clock();
    double time_spent = double(end - begin) / CLOCKS_PER_SEC;
    cout << "Time complexity for clearing the queue is: " << time_spent << " seconds." << endl;

    if(q.empty()) {
        cout << "Queue is now empty." << endl;
    } else {
        cout << "There are still elements in the queue." << endl;
    }

    return 0;
}
```

Instead of popping elements one by one, we directly initialize q with empty queue (q = queue<int>()) which can clear the queue in O(1) time. However, this is not a guaranteed time complexity and the actual time complexity depends heavily on implementation details of STL.

