```python
class ChessPiece:
    def __init__(self, color, type):
        self.color = color
        self.type = type

class ChessBoard:
    def __init__(self):
        self.board = self.create_board()

    def create_board(self):
        # Initialize an 8x8 chess board with None placeholders
        return [[None for _ in range(8)] for _ in range(8)]

    def place_piece(self, piece, x, y):
        self.board[y][x] = piece

    def move_piece(self, start, end):
        # Validate the movement of chess piece
        x1, y1 = start
        x2, y2 = end
        piece = self.board[y1][x1]

        if piece is None:
            raise ValueError("There is no piece at the starting position.")

        validation_dict = {
            'king': self.validate_king_movement,
            'bishop': self.validate_bishop_movement,
            'knight': self.validate_knight_movement,
            'queen': self.validate_queen_movement
        }

        is_valid_move = validation_dict[piece.type](start, end)

        if not is_valid_move:
            raise ValueError("Invalid move for the piece type.")

        # If valid, move the piece on the board
        self.board[y2][x2] = piece
        self.board[y1][x1] = None

    def validate_king_movement(self, start, end):
        x1, y1 = start
        x2, y2 = end
        return max(abs(x1-x2), abs(y1-y2)) == 1

    def validate_knight_movement(self, start, end):
        x1, y1 = start
        x2, y2 = end
        return (abs(x1-x2), abs(y1-y2)) in ((1, 2), (2, 1))

    def validate_bishop_movement(self, start, end):
        x1, y1 = start
        x2, y2 = end
        return abs(x2 - x1) == abs(y2 - y1)

    def validate_queen_movement(self, start, end):
        return self.validate_king_movement(start, end) or \
               self.validate_bishop_movement(start, end)
```

