// Prime number generation 
function generatePrimes(n) {
  let sieve = [], i, j, primes = [];
  for (i = 2; i <= n; ++i) {
    if (!sieve[i]) {
      // i has not been marked -- it is a prime
      primes.push(i);
      for (j = i << 1; j <= n; j += i) {
        sieve[j] = true;
      }
