        PrintArray(array);  
        array = ReverseArray(array);  
        Console.WriteLine("\nReversed Array Elements:");  
        PrintArray(array);  
        Console.ReadKey();
    }

    static int[] ReverseArray(int []array)  
    {  
        int [] new_array = new int[array.Length];    
        int reversecount = 0;  
        for (int i = array.Length - 1; i >= 0; i--) 
        {  
            new_array[reversecount] = array[i];  
            reversecount++;  
        }   
        return new_array;
    }  

    static void PrintArray(int[] array)  
    {   
        foreach (int i in array)  
        {  
            Console.Write(i + " ");  
        }  
    }  
}  

This C# program creates an array of integers, prints out the original array, then reverses the array using a separate method ReverseArray. After reversing, it then prints out the reversed array. The ReverseArray method takes an integer array as a parameter, creates a new array with the same length, and then in a for loop iterates backwards through the original array, assigning each value to the new array. The new, reversed array is returned and passed to the PrintArray method to print each element out to the console.

