```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("Please input a sentence: ");
        Scanner sc = new Scanner(System.in);
        String sentence = sc.nextLine();
        System.out.println(most_common_word(sentence));
    }

    public static String most_common_word(String sentence) {
        String[] words = sentence.split(" ");
        HashMap<String, Integer> word_count = new HashMap<String, Integer>();
        for (String word : words) {
            word = word.toLowerCase();
            if (!word_count.containsKey(word)) {
                word_count.put(word, 1);
            } else {
                word_count.put(word, word_count.get(word) + 1);
            }
        }
        String max_word = (Collections.max(word_count.entrySet(), Map.Entry.comparingByValue())).getKey();
        return max_word;
    }
}
