```javascript
function factorial(n) {
    // Verify if 'n' is a positive integer
    if (n < 0 || !Number.isInteger(n)) {
        console.log('Error: Input must be a positive integer.');
        return;
    }

    // Account for the case where 'n' equals zero
    if (n === 0) {
        return 1;
    }

    // Compute the factorial of 'n' via recursion
    return n * factorial(n - 1);
}
