Perfect numbers are positive integers that are equal to the sum of its positive divisors excluding the number itself. And Happy numbers are numbers in which eventually reaches 1 when replaced by the sum of the square of each digit repeatedly.

Following is the JavaScript Solution:

```javascript
function findPerfectNumbers(n) {
    let perfectNumbers = [];
    for(let i=1; i<=n; i++){
        let sum = 0;
        for(let j=1; j<i; j++){
            if(i % j === 0)
                sum += j;
        }
        if(sum === i)
            perfectNumbers.push(i);
    }
    return perfectNumbers;
}

function isHappyNumber(n) {
    let slow = n;
    let fast = n;
    do {
        slow = squareDigitSum(slow);
        fast = squareDigitSum(squareDigitSum(fast));
    } while (slow !== fast)
    return slow === 1;
}

function squareDigitSum(n) {
    let sum = 0;
    while (n !== 0) {
        let digit = n % 10;
        sum += digit * digit;
        n = Math.floor(n / 10);
    }
    return sum;
}

let perfectNumbers = findPerfectNumbers(10000);
for(let num of perfectNumbers){
    if(isHappyNumber(num)){
        console.log(num + " is a perfect and a happy number");
    }
}
```

In function `findPerfectNumbers(n)`, we are finding perfect numbers up to `n`. And, `isHappyNumber(n)` is checking the number is a happy number or not. In the last loop, we are checking all perfect numbers from the list if they are also happy numbers or not. The numbers that are both perfect and happy will be printed.

Please Note, the edge cases are considered where in function `isHappyNumber(n)`, checking if n is 1 and similarly in `findPerfectNumbers(n)`, checking if the sum is equal to the number or not. The code is optimized in terms of space complexity and time by using the Tortoise and Hare (Floyd's cycle finding algorithm) method.

