Here is a python program using regular expression.

```python
import re
import unittest

def email_parser(email_address):
    pattern = re.compile(r"^[a-zA-Z0-9_.+-]+@(?P<secondlevel>[a-zA-Z0-9-]+)\.(?P<toplevel>[a-zA-Z0-9-.]+$)")
    match = pattern.match(email_address)

    if match is None:
        return False

    if match.group('toplevel') in ['gov','edu','org'] or match.group('secondlevel') in ['gmail','yahoo','outlook']:
        domain_type = 'special'
    else:
        domain_type = 'normal'

    return {
        'secondlevel': match.group('secondlevel'),
        'toplevel': match.group('toplevel'),
        'domain_type': domain_type,
    }

class TestEmailParser(unittest.TestCase):

    def test_normal_domains(self):
        self.assertEqual(email_parser('test.example@gmail.com'),
            {'secondlevel': 'gmail', 'toplevel': 'com', 'domain_type': 'special'})

    def test_special_domains(self):
        self.assertEqual(email_parser('test.example@abc.gov'),
            {'secondlevel': 'abc', 'toplevel': 'gov', 'domain_type': 'special'})

    def test_subdomains(self):
