Here is a C++ function that removes a node from a doubly linked list by a specific value. This function travels throughout the linked list, and when it finds the node containing the specific value, it changes the previous node's next pointer and next node's previous pointer to disregard the unwanted node.

```cpp
#include<iostream>
using namespace std;

// A Linked List Node
struct Node
{
    int data;
    Node* next;
    Node* prev; 
};

// Function to insert into a Doubly Linked List
void insert(Node** head_ref, int new_data)
{
    Node* node = new Node(); /* allocate node */
    node->data = new_data; /* put in the data */

    /* since we are adding at the beginning, prev is always NULL */
    node->prev = NULL;

    /* link the old list off the new node */
    node->next = (*head_ref); 

    /* change prev of head node to new node */
    if ((*head_ref) != NULL)
        (*head_ref)->prev = node;

    /* move the head to point to the new node */
    (*head_ref) = node;
}

// Function to delete a given node from the list
void deleteNode(Node** head_ref, int key) {
    // If list is empty
    if (*head_ref == NULL)
        return;

    // Find the required node
    Node* temp = *head_ref;
    while(temp != NULL && temp->data != key)
        temp = temp->next;

    // If key was not present in list
    if(temp == NULL){
        cout << "The given key is not in list" << endl;
        return;
    }

    // If node to be deleted is head node
    if(*head_ref == temp)
        *head_ref = temp->next;

    // Change next only if node to be deleted is NOT the last node
    if(temp->next != NULL)
        temp->next->prev = temp->prev;

    // Change prev only if node to be deleted is NOT the first node
    if(temp->prev != NULL)
        temp->prev->next = temp->next;

    // Finally, free the memory occupied by temp
    delete temp;
    return;
}

```

You can use the `insert` function to insert new elements into the list to test this, then use the `deleteNode` function to delete a node by its value.

