FindMax class:

```java
import java.util.concurrent.atomic.AtomicInteger;

public class FindMax implements Runnable {

    private int num;
    private AtomicInteger max;

    public FindMax(int num, AtomicInteger max) {
        this.num = num;
        this.max = max;
    }

    @Override
    public void run() {
        synchronized (max) {
            if (num > max.get()) {
                max.set(num);
            }
        }
    }
}
