function shortestCommonSuffix(str1, str2) {
  let commonSuffix = '';

  for (let i = 1; i <= Math.min(str1.length, str2.length); i++) {
    if (str1[str1.length - i] === str2[str2.length - i]) {
      commonSuffix = str1[str1.length - i] + commonSuffix;
