    }
}

class ReaderThread implements Runnable {
    private Data data;

    public ReaderThread(Data data) {
        this.data = data;
    }

    @Override
    public void run() {
        while (true) {
            data.readValue();
        }
    }
}

class ProcessorThread implements Runnable {
    private Data data;

    public ProcessorThread(Data data) {
        this.data = data;
    }

    @Override
    public void run() {
        while (true) {
            data.processValue();
        }
