125 1.709975946676697
-125 nan
```

The `nan` here stands for 'not a number'. The reason is that in mathematics, the cube root of a negative number is a complex number, and our function is defined to return a float64, not a complex number. We can add handling of negative numbers in the `cubeAndCubeRoot` function, and return results in complex numbers like this:

```go
package main

import (
	"fmt"
	"math"
	"math/cmplx"
)

func main() {
	fmt.Println(cubeAndCubeRoot(5))
	fmt.Println(cubeAndCubeRoot(-5))
}

func cubeAndCubeRoot(n int) (complex128, complex128) {
	cube := complex(n * n * n, 0)
	var cubeRoot complex128
	if n >= 0 {
		cubeRoot = cmplx.Pow(complex(float64(n), 0), 1.0/3)
	} else {
		cubeRoot = cmplx.Pow(complex(float64(n), 0), 1.0/3)
	}
	return cube, cubeRoot
}
```

