import json

def sort_fruits(json_string):
    data = json.loads(json_string)
    sorted_data = {}

    # Sort the keys of the nested dictionary in reverse order
    for key, value in data.items():
        if isinstance(value, dict):
            sorted_data[key] = {k: v for k, v in sorted(value.items(), key=lambda x: x[0], reverse=True)}

    # Add the other key-value pairs
    for key, value in sorted(data.items(), key=lambda x: x[1].lower()):
        if not isinstance(value, dict):
            sorted_data[key] = value

    return sorted_data


