```python
def check_chars(s,index,count_dict):
    vowels = set("aeiou")
    alphabet = set("abcdefghijklmnopqrstuvwxyz")

    if index == len(s):
        return count_dict
    char = s[index].lower()
    if char in vowels:
        count_dict['vowels'] += 1
    elif char in alphabet:
        count_dict['consonants'] += 1
    elif char.isdigit():
        count_dict['numeric'] += 1
    elif char.isspace():
        count_dict['space'] += 1
    else:
        count_dict['special'] += 1
    return check_chars(s,index+1,count_dict)

