Here is the Python code which implements Undo-Redo operation using classes.

```python
class UndoRedo:
    def __init__(self):
        self.commands = []
        self.current = -1

    def undo(self):
        if self.current < 0:
            print("Nothing to undo")
            return
        command = self.commands[self.current]
        command.undo()
        self.current -= 1

    def redo(self):
        if self.current + 1 >= len(self.commands):
            print("Nothing to redo")
            return
        self.current += 1
        command = self.commands[self.current]
        command.redo()

    def add_command(self, command):
        # If we are not at the end of the stack get rid of everything after current.
        if self.current < len(self.commands) - 1:
            self.commands = self.commands[:(self.current+1)]

        self.commands.append(command)
        self.current = len(self.commands) - 1

# Define an interface (abstract base class) for commands.
# ConcreteCommand class
class Command:
    def __init__(self, receiver):
        self.receiver = receiver

    def undo(self):
        pass

    def redo(self):
        pass

# This is an example of concrete commands.
# In a real project, these commands could be anything like moving a graphical object, inserting text, etc.
class PrintCommand(Command):
    def __init__(self, receiver, text):
        super().__init__(receiver)
        self.text = text

    def undo(self):
        self.receiver.undo_print(self.text)

    def redo(self):
        self.receiver.redo_print(self.text)


# Receiver class
class Printer:
    def undo_print(self, text):
        print(f'Undo print "{text}"')

    def redo_print(self, text):
        print(f'Redo print "{text}"')

# Testing undo-redo class
printer = Printer()
undo_redo = UndoRedo()

undo_redo.add_command(PrintCommand(printer, 'Hello, World!'))

undo_redo.undo()
undo_redo.redo()
undo_redo.redo()
```
In this case, I’ve made "print operation" undoable. After invoking `undo_redo.undo()` you will see that it is undoing print and after invoking `undo_redo.redo()` you will see that it is redoing print operation. This implementation is an example of the Command Design Pattern, where commands hold receiver and invoke methods on the receiver when the command's execute method is called.

