```javascript
const regexMatch = (str) => {
    try {
        if (typeof str !== 'string') {
            throw new Error('Non-string inputs are not accepted');
        }
        if (!str) {
            return 'Input string cannot be empty';
        }

        const regex = /^[0-9]*$/;

        if (!regex.test(str)) {
            return 'Input string has non-numeric characters';
        }

        const evenCount = str.split('').filter(c => parseInt(c, 10) % 2 === 0).length;
        return `The input string is numeric and has ${evenCount} even digits`;

