function generateTable(data) {
    // Check if input is an array, if not throw an Error
    if (!Array.isArray(data)) {
        throw new Error("Input must be an array");
    }

    let table = "<table><tr><th>Name</th><th>Wins</th><th>Losses</th><th>Draws</th></tr>";
    for (let i = 0; i < data.length; i++) {
