To solve this problem, you can use the `chr()` and `ord()` functions in Python to easily shift characters by 13 positions. Here's the code for both encoding and decoding ROT13:

```python
def rot13_encode(text):
    encoded_text = []

    for char in text:
        if 'A' <= char <= 'Z':
            offset = ord('A')
            encoded_char = chr((ord(char) - offset + 13) % 26 + offset)
        elif 'a' <= char <= 'z':
            offset = ord('a')
            encoded_char = chr((ord(char) - offset + 13) % 26 + offset)
        else:
            encoded_char = char

        encoded_text.append(encoded_char)

    return ''.join(encoded_text)

def rot13_decode(encoded_text):
    decoded_text = []

    for char in encoded_text:
        if 'A' <= char <= 'Z':
            offset = ord('A')
            decoded_char = chr((ord(char) - offset - 13) % 26 + offset)
        elif 'a' <= char <= 'z':
            offset = ord('a')
            decoded_char = chr((ord(char) - offset - 13) % 26 + offset)
        else:
            decoded_char = char

        decoded_text.append(decoded_char)

    return ''.join(decoded_text)

if __name__ == "__main__":
    text = "Hello World!"
    encoded_text = rot13_encode(text)
    decoded_text = rot13_decode(encoded_text)

    print("Original text:", text)
    print("Encoded text:", encoded_text)
    print("Decoded text:", decoded_text)
```

Output:

```
Original text: Hello World!
Encoded text: Uryyb Jbeyq!
Decoded text: Hello World!
```

You can see that the `rot13_encode()` function converges the original text into its ROT13-encoded form, while the `rot13_decode()` function decodes it back to the original text.

