import requests
from urllib.parse import urlparse
from requests.exceptions import MissingSchema, InvalidURL, ConnectionError

def construct_url(protocol, subdomain, domain, path):
    return f"{protocol}://{subdomain}.{domain}.com/{path}"

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def is_reachable_url(url):
    try:
        response = requests.get(url)
        return response.status_code == 200
    except (MissingSchema, InvalidURL, ConnectionError):
        return False

def main():
    protocol = "https"
    subdomain = "mypage"
    domain = "google"
    path = "search"

    url = construct_url(protocol, subdomain, domain, path)

    print(f"Constructed URL: {url}")

    if is_valid_url(url):
        print("URL is valid.")
    else:
        print("URL is not valid.")

    if is_reachable_url(url):
        print("URL is reachable.")
    else:
        print("URL is not reachable.")

if __name__ == "__main__":
    main()
```

