In this function, we firstly check the size of the vector. If it is 0 or 1 print out an error message and return. Then we initially set the smallest and largest values to be the first element of the vector and their counts to be 1. After we go through each element in the vector, if we find a smaller or larger number, we update the smallest or largest value and reset the count. If we encounter the same smallest or largest number, then we increment the count.

```c++
#include<bits/stdc++.h>
using namespace std;

pair<pair<int, int>, pair<int, int>> findSmallestAndLargest(vector<int> nums) {
    // check the size of vector
    if (nums.size() <= 1) {
        cout << "Error! The array either consists of one element or is empty!" << endl;
        return make_pair(make_pair(0, 0), make_pair(0, 0));
    }

    int smallest = nums[0], largest = nums[0], smallestCount = 1, largestCount = 1;

    for (int i = 1; i < nums.size(); i++) {
        if (nums[i] < smallest) {
            smallest = nums[i];
            smallestCount = 1;
        } else if (nums[i] == smallest) {
            smallestCount++;
        }

        if (nums[i] > largest) {
            largest = nums[i];
            largestCount = 1;
        } else if (nums[i] == largest) {
            largestCount++;
        }
    }

    return make_pair(make_pair(smallest, smallestCount), make_pair(largest, largestCount));
}
