Here is a JavaScript solution to this problem:

```javascript
function sortJSON(array, key, order='asc') {

    // Type checking for arguments
    if (!Array.isArray(array)) {
        throw new Error("Input is not an array");
    }

    if (typeof key !== 'string') {
        throw new Error("Key is not a string");
    } 

    if (order !== 'asc' && order !== 'desc') {
        throw new Error("Order is neither 'asc' nor 'desc'");
    }

    // Check if array is empty
    if (array.length === 0) {
        return '[]';
    }

    // Check if key exists in the first object
    if (!array[0].hasOwnProperty(key)) {
        throw new Error(`Key "${key}" not found in the objects`);
    }

    // Sorting
    let sortedArray = array.sort((a, b) => {
        // Deal with potential type mismatch
        if (typeof a[key] !== typeof b[key]) {
            throw new Error('Type mismatch for key values');
        }

        return (order === 'asc') ? (a[key] > b[key] ? 1 : -1) : (a[key] < b[key] ? 1 : -1);
    });

    // Convert to string of JSON objects
    return JSON.stringify(sortedArray);
}
```

