Here's a sample algorithm to balance a Binary Search tree in JavaScript, the algorithm used here is AVL Tree which is a self-balancing Binary Search Tree.

The tree balances itself after every insert and delete operation to ensure minimum height. 

Below is a JavaScript class that represents a Node of the tree:

```javascript
class Node {
    constructor(data, left = null, right = null) {
        this.data = data;
        this.left = left;
        this.right = right;
        this.height = 1;
    }
}
```

Here is the JavaScript class for the implementation of AVL Trees:

```javascript
class AVLTree {
    constructor() {
        this.root = null;
    }

    height(node) {
        if (node === null) {
            return 0;
        }
        return node.height;
    }

    max(a, b) {
        return (a > b) ? a : b;
    }

    rotateRight(y) {
        let x = y.left;
        let T2 = x.right;

        x.right = y;
        y.left = T2;

        y.height = this.max(this.height(y.left), this.height(y.right)) + 1;
        x.height = this.max(this.height(x.left), this.height(x.right)) + 1;

        return x;
    }

    rotateLeft(x) {
        let y = x.right;
        let T2 = y.left;

        y.left = x;
        x.right = T2;

        x.height = this.max(this.height(x.left), this.height(x.right)) + 1;
        y.height = this.max(this.height(y.left), this.height(y.right)) + 1;

        return y;
    }

    getBalance(node) {
        if (node === null) {
            return 0;
        }
        return this.height(node.left) - this.height(node.right);
    }

    insert(data) {
        let node = new Node(data);
        if (this.root === null) {
            this.root = node;
        } else {
            this.root = this.insertNode(this.root, node);
        }
    }

    insertNode(node, newNode) {
        if (node === null) {
            node = newNode;
        } else if (newNode.data < node.data) {
            node.left = this.insertNode(node.left, newNode);
            node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
        } else if (newNode.data > node.data) {
            node.right = this.insertNode(node.right, newNode);
            node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
        }

        let balance = this.getBalance(node);

        if (balance > 1 && data < node.left.data) {
            return this.rotateRight(node);
        }

        if (balance < -1 && data > node.right.data) {
            return this.rotateLeft(node);
        }

        if (balance > 1 && data > node.left.data) {
            node.left = this.rotateLeft(node.left);
            return this.rotateRight(node);
        }

        if (balance < -1 && data < node.right.data) {
            node.right = this.rotateRight(node.right);
            return this.rotateLeft(node);
        }

        return node;
    }

    // other methods like delete and search go here...
}
```

This program creates AVLTree class and Node class. It uses AVL tree logic to maintain balance and does re-balancing after every insertion. Note that this just an example, there are more efficient balancing algorithms available.

