double findMedian(std::vector<double>& nums, int size) {
    std::sort(nums.begin(), nums.end());
    if (size % 2 != 0)
        return (double)nums[size / 2];

    return (double)(nums[(size - 1) / 2] + nums[size / 2]) / 2.0;
}

int main() {
    std::vector<double> vec = {1.5, 5.0, -4.5, 2.5, 3.0};
    int size = vec.size();
