func Gather(number, need, remaining int) []int {
    var totalNuts, remainingNuts int
    if need > remaining {
        totalNuts = number + remaining
        remainingNuts = need - remaining
        remainingNuts = 0 - remainingNuts
    } else {
        totalNuts = number + need
        remainingNuts = remaining - need
