using namespace std;

string LongestPalindrome(string str1, string str2) {
    int m = str1.size(), n = str2.size();

    int dp[m+1][n+1];
    memset(dp, 0, sizeof(dp));

    for(int i=0; i<=m; i++) {
        for(int j=0; j<=n; j++) {
            if(i==0 || j==0)
                dp[i][j] = 0;
            else if(str1[i-1] == str2[j-1])
                dp[i][j] = 1 + dp[i-1][j-1];
            else
                dp[i][j] = max(dp[i][j-1], dp[i-1][j]);
        }
    }

    int index = dp[m][n];
    string res(index, ' ');

    int i = m, j = n;
    while(i > 0 && j > 0) {
        if(str1[i-1] == str2[j-1]) {
            res[index-1] = str1[i-1];
            i--;
            j--;
            index--;
        } else if(dp[i-1][j] > dp[i][j-1]) 
            i--;
        else 
            j--;
    }

    return res;
}

int main() {
    string str1, str2;
    cout << "Enter first string: ";
    cin >> str1;
    cout << "Enter second string: ";
    cin >> str2;

    string res = LongestPalindrome(str1, str2);
    cout << "Longest Palindrome: " << res << "\n";

    return 0;
}
```

This code gives you the longest common substring from the given two strings which is also a palindrome. First, it computes the longest common subsequence (LCS) of str1 and str2. Then it prints the LCS. The space complexity is O(mn) where m and n are lengths of two input strings.

