#include <stdio.h>
#include <stdint.h>

int32_t find_largest(int32_t x, int32_t y, int32_t z){
    int32_t f_xy = ((y - x) >> 31) & 1; // f_xy will be 1 if x < y, 0 otherwise
    int32_t m_xy = f_xy * x + (1 - f_xy) * y; // m_xy will be the maximum of x and y

    int32_t f_mz = ((z - m_xy) >> 31) & 1; // f_mz will be 1 if m_xy < z, 0 otherwise
    int32_t largest = f_mz * m_xy + (1 - f_mz) * z; //largest will be maximum of m_xy and z

    return largest;
}

