def calculate_average(grades_dict):
    if not isinstance(grades_dict, dict):
        raise ValueError("Input must be a dictionary.")
    result = {}
    for student, grades in grades_dict.items():
        if not isinstance(student, str):
            raise TypeError("Student's name must be a string.")
        if not isinstance(grades, list):
            raise TypeError("Grades must be a list.")
        if not all(isinstance(grade, (int, float)) for grade in grades):
            raise ValueError("All grades must be numbers.")
        if not all(0 <= grade <= 100 for grade in grades):
            raise ValueError("All grades must be between 0 and 100.")
        if len(grades) > 5:
            grades.remove(min(grades))
        result[student] = sum(grades)/len(grades)
    return result
