Below is a C# function `PerformSubstitution` which achieves your requirements. This function uses the `StringBuilder` class for efficient string manipulation. It also checks for null or non-string inputs and handles them appropriately.

```csharp
using System;
using System.Text;
using System.Linq;

public class Program
{
    public static void Main()
    {
        string input = "Timon and Pumbaa";
        Console.WriteLine(PerformSubstitution(input));

        // Try with null input
        Console.WriteLine(PerformSubstitution(null));

        // Try with integer input
        Console.WriteLine(PerformSubstitution(12345));
    }

    public static string PerformSubstitution(object input)
    {
        if (input == null) return "Input cannot be null"; 
        if(!(input is string)) return "Input must be string";

        StringBuilder str = new StringBuilder((string)input);
        for (int i = 0; i < str.Length; i++)
        {
            if (str[i] == 'a') str[i] = 'o';
            if (char.ToLower(str[i]) == 'i') str[i] = Char.IsLower(str[i]) ? 'e' : 'E';

            if (i + 1 < str.Length && char.IsLetter(str[i]) && !char.IsLetter(str[i + 1]) ||
                i == str.Length - 1 && char.IsLetter(str[i]))
            {
                char lowerCaseChar = Char.ToLower(str[i]);
                if (lowerCaseChar != 'a' && lowerCaseChar != 'e' &&
                    lowerCaseChar != 'i' && lowerCaseChar != 'o' && lowerCaseChar != 'u')
                {
                    str[i] = 'z';
                }
            }
        }
        return str.ToString();
    }
}
```

