```solidity
//Version of Solidity compiler this code was written for
pragma solidity ^0.5.16;

contract Bet {

    address payable public gambler;
    uint public betAmount;
    uint public betNumber;
    bool public betActive;

    event Won(bool win, uint256 payout);

    // Start the bet
    function startBet(uint _betNumber) public payable {
        // Conditions required for the bet
        require(!betActive);
        require(msg.value > 0.01 ether);

        betActive = true;
        betNumber = _betNumber;
        betAmount = msg.value;
        gambler = msg.sender;
    }

    // Execute the bet
    function executeBet() public {
        require(betActive);
        uint winningNumber = block.number % 10 + 1;

        // Payout whenever the winningNumber equals betNumber
        if (betNumber == winningNumber) {
            uint amountWon = betAmount * 8;
            if(!gambler.send(amountWon)) {
                revert();
            }
            emit Won(true, amountWon);
        } else {
            emit Won(false, 0);
        }
        resetBet();
    }

    // Function to reset the bet after completion
    function resetBet() internal {
        betActive = false;
        betAmount = 0;
        betNumber = 0;
        gambler = address(0);
    }

    // Function for the owner to withdraw the funds
    function fundsWithdrawal(uint amount) public {
        if(msg.sender != gambler) {
            revert();
        }
        if(!gambler.send(amount)) {
            revert();
        }
    }
}
