Here is a simple C# console application code, which illustrates the pre-order traversal on Binary Tree:

```C#
using System;

public class Node
{
    public int Value;
    public Node LeftChild, RightChild;

    public Node(int value)
    {
        this.Value = value;
        LeftChild = RightChild = null;
    }
}

public class BinaryTree
{
    public Node Root;

    public BinaryTree()
    {
        Root = null;
    }

    public void PreOrderTraversal(Node node)
    {
        if (node == null)
            return;

        Console.Write(node.Value + " "); 
        PreOrderTraversal(node.LeftChild); // Traverse the left sub-tree
        PreOrderTraversal(node.RightChild); // Traverse the right sub-tree
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        BinaryTree binaryTree = new BinaryTree();
        binaryTree.Root = new Node(1);
        binaryTree.Root.LeftChild = new Node(2);
        binaryTree.Root.RightChild = new Node(3);
        binaryTree.Root.LeftChild.LeftChild = new Node(4);
        binaryTree.Root.LeftChild.RightChild = new Node(5);

        Console.WriteLine("Pre-Order Traversal of binary tree is: ");
        binaryTree.PreOrderTraversal(binaryTree.Root);

        Console.ReadLine();
    }
}
