    int arr[] = {2, 8, 15, 1, 15, 3, 9, 15};  // Array of integers
    int n = sizeof(arr) / sizeof(arr[0]);  // size of array
    int max = findMaximum(arr, n);  // find maximum value in the array
    int count = countRepeated(arr, n, max);  // count repetition of maximum value in the array

