int findMaximum(int arr[], int n) {
    int i;
    int max = arr[0];  // Assume first number in array is the largest initially

    for(i = 1; i < n; i++) {
        if(arr[i] > max) {
            max = arr[i];   // Update the maximum
        }
    }

    return max;  // return maximum value
}

// Function to count the repetition of max in arr[]
int countRepeated(int arr[], int n, int max) {
    int i;
    int count = 0;  // counter for max

    for(i = 0; i < n; i++) {
        if(arr[i] == max) {
            count++;   // increment the counter
        }
    }

    return count;  // return the count
}
