def max_profit(stock_prices):
    day_trade_charge = 0.0002
    short_sell_rate = 0.005
    long_term_trade_charge = 0.005
    profit_day = []
    profit_short_sell = []

    total_profit_day = 0
    total_profit_short_sell = 0
    n = len(stock_prices)

    for i in range(n-1):
        profit_day.append((stock_prices[i+1]-stock_prices[i])-(stock_prices[i+1]*day_trade_charge +stock_prices[i]*day_trade_charge))
        if(stock_prices[i]>stock_prices[i+1]):
