        else:
            profit_short_sell.append(-(stock_prices[i]-stock_prices[i+1])-(stock_prices[i+1]*short_sell_rate +stock_prices[i]*short_sell_rate))

    max_profit_long_term = max(stock_prices)-min(stock_prices)-(max(stock_prices)*long_term_trade_charge +min(stock_prices)*long_term_trade_charge)
    total_profit_day = sum(profit_day)
    total_profit_short_sell = sum(profit_short_sell)

    if (max_profit_long_term>total_profit_day) and (max_profit_long_term>total_profit_short_sell):
        return ("Max Profit can be achieved from Long Term Trading", max_profit_long_term)
    elif (total_profit_day>max_profit_long_term) and (total_profit_day>total_profit_short_sell):
        return ("Max Profit can be achieved from Day Trading", total_profit_day)
    else:
        return ("Max Profit can be achieved from Short Selling", total_profit_short_sell)

