```python
# 简单的Python计算器，能处理数字并执行基本运算。
class Calculator:
    def __init__(self):
        self.variables = {}

    def calculate(self):
        while True:
            expr = input('请输入一个表达式（例如：A + B * C，或 quit 退出）: ')
            if expr == 'quit':
                break
            try:
                if '=' in expr:
                    # 处理赋值操作符 '=', 如 'A = 10'
                    var, value = expr.split('=')
                    self.variables[var.strip()] = self.eval_expr(value.strip())
                else:
                    print(self.eval_expr(expr))
            except ZeroDivisionError:
                print('除数不能为0！')
            except Exception as e:
                print(f'非法输入：{e}')

    def eval_expr(self, expr):
        # 使用python的内置eval函数来计算数学表达式，其中vars参数可以提供变量的当前值。
        return eval(expr, {}, self.variables)


# 运行计算器
if __name__ == "__main__":
    calc = Calculator()
    calc.calculate()
```
