```java
public class Main {

    private static String[] exceptionWords = { "a", "an", "the", "and", "but", "or", "for", "nor", "on", "at", "to", "from", "by", "in", "of" };

    public static void main(String[] args) {

        System.out.println(toTitleCase("into the wild"));     // Test case 1
        System.out.println(toTitleCase("of mice and men"));  // Test case 2
    }

    public static String toTitleCase(String input) {
        String[] words = input.split(" ");
        for (int index = 0; index < words.length; index++) {
            if (index == 0 || index == words.length - 1 || !isExceptionWord(words[index])) {
                words[index] = words[index].substring(0, 1).toUpperCase() + words[index].substring(1);
            }
        }
        return String.join(" ", words);
    }

    private static boolean isExceptionWord(String word) {
        for (String exceptionWord : exceptionWords) {
            if (exceptionWord.equals(word))
                return true;
        }
        return false;
    }
}
```

