function orderByAttribute(arr, attr) {
    return arr.sort((a, b) => {
        // If the selected attribute are numbers, sort by the difference. (numeric sort)
        if (typeof a[attr] === 'number' && typeof b[attr] === 'number') {
            return a[attr] - b[attr];
        }
        // If the selected attribute is not number then covert their value to string and compare.(string sort)
        return String(a[attr]).localeCompare(String(b[attr]));
    });
}

