``` php 
 function reverseArray($inputArray){ 
  $ reversedArray= []; 
   foreach (array_reverse($inputArray) as$ subArray){ 
     if (is_array($subArray)){ 
      $ reversedArray []= array_reverse($subArray); 
    } else{ 
      $ reversedArray []=$ subArray; 
    } 
  } 
   return$ reversedArray; 
} 
