This problem can be solved using recursive calls and backtracking techniques, when the sum of the current combination equals to your target, you can add this combination to your result array. Here is the JavaScript function:

```javascript
function combinationSum(arr, target) {
    let result = [];
    backtrack(result, arr, target, [], 0);
    return result;
}

function backtrack(result, arr, remain, tmpArr, start) {
    if(remain < 0) 
        return;
    else if(remain === 0)
        result.push(tmpArr.slice());
    else {
        for(let i = start; i < arr.length; i++) {
            tmpArr.push(arr[i]);
            backtrack(result, arr, remain - arr[i], tmpArr, i + 1);
            tmpArr.pop();
        }
    }
}

let array = [2, 3, 7, 8, 10];
let target = 11;
console.log(combinationSum(array, target));
```

