```Javascript
class DataSetChecker {
  constructor(dataSet1, dataSet2) {
    this.dataSet1 = dataSet1;
    this.dataSet2 = dataSet2;
  }

  isEqualTo() {
    if (this.dataSet1.length !== this.dataSet2.length) {
      return false;
    } else {
      for (let i = 0; i < this.dataSet1.length; i++) {
        if (this.dataSet1[i] !== this.dataSet2[i]) {
          return false;
        }
      }
      return true;
    }
  }

  isEqualToObject() {
    return JSON.stringify(this.dataSet1) === JSON.stringify(this.dataSet2);
  }
}

// USAGE
