// helper function to check if a number is prime
function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  if (num == 2) {
    return true;
  }
  if (num % 2 == 0) {
    return false;
  }
  for (let i = 3; i * i <= num; i += 2) {
    if (num % i == 0) {
      return false;
    }
  }
  return true;
}

// helper function to check if a number is even
function isEven(num) {
  return num % 2 == 0;
}

// main function to compute the ratio
function primeToEvenRatio(numbers) {
  let primeCount = 0;
  let evenCount = 0;

  for (let num of numbers) {
    if (isPrime(num)) {
      primeCount++;
    }
    if (isEven(num)) {
      evenCount++;
    }
  }

  return primeCount / evenCount;
}

console.log(primeToEvenRatio([2, 3, 4, 5, 6, 7, 8, 9, 10])); // output: 0.8
```
The `isPrime` function checks if a number is prime or not. The `isEven` function checks if a number is even or not. The `primeToEvenRatio` function goes through the given array and counts the number of primes and evens using the helper functions, then returns the ratio.

