function findFirstMissingIndex(inputArray) {
    let sortedArray = inputArray.sort((a, b) => a - b);
    let firstMissingIndex = -1;

    if (sortedArray[0] > 1) {
      return 1;
    } 

    for(let i = 0; i < sortedArray.length; i++) {
        if (sortedArray[i] < 0) {
          continue;
