public class Main {
    static String removeChar(String str, char c) {
        if (str == null)
            return null;
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < str.length()) {
            //如果當前字符和指定的字符相等，同時以下一個字符為同樣的字符，則找出所有連續的該字符並跳過它們
            if (str.charAt(i) == c && (i + 1) < str.length() && str.charAt(i + 1) == c) {
                while (i < str.length() && str.charAt(i) == c) {
                    i++;
                }
            } else {
                sb.append(str.charAt(i)); //如果當前字符不是指定字符，則將其添加到結果中。
                i++;
            }
        }
