import React, { Component } from 'react';


class RegistrationForm extends Component {

  constructor() {
    super();
    this.state = {
      fields: {},
      errors: {}
    }
  }

  handleValidation(){
    let fields = this.state.fields;
    let errors = {};
    let formIsValid = true;

    if(!fields["firstName"]){
      formIsValid = false;
      errors["firstName"] = "Cannot be empty";
    }

    if(!fields["lastName"]){
      formIsValid = false;
      errors["lastName"] = "Cannot be empty";
    }       
