```java
public class Employee {
    private String name;
    private int age; 
    private String jobTitle;

    //Constructor for employee
    public Employee(String name, int age, String jobTitle) throws IllegalArgumentException {
        this.setName(name);
        this.setAge(age); 
        this.setJobTitle(jobTitle);
    }

    //Methods to set employee parameters with error checking

    public void setName(String name) throws IllegalArgumentException {
        if (!(name instanceof String)) {
            throw new IllegalArgumentException("Invalid input type. Name must be a string.");
        }  
        this.name = name;
    }

    public void setAge(int age) throws IllegalArgumentException {
        if (!(age instanceof Integer)) {
            throw new IllegalArgumentException("Invalid input type. Age must be an integer.");
        }
        if (age < 18 || age > 65) {
            throw new IllegalArgumentException("Invalid input value. Age must be between 18 and 65.");
        }
        this.age = age; 
    }

    public void setJobTitle(String jobTitle) throws IllegalArgumentException {
        if (!(jobTitle instanceof String)) {
            throw new IllegalArgumentException("Invalid input type. Job Title must be a string.");
        }
        this.jobTitle = jobTitle; 
    }

    //Methods to get employee parameters

    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public String getJobTitle() {
        return jobTitle;
    }

}
