        this.msPerDay = this.msPerHour * 24;
        this.msPerMonth = this.msPerDay * 30;
        this.msPerYear = this.msPerDay * 365;

        this.date1 = new Date(date1);
        this.date2 = new Date(date2);
        this.difference = this.date2 - this.date1;
    }

    differenceInYears() {
        return Math.floor(this.difference / this.msPerYear);
    }

    differenceInMonths() {
        return Math.floor((this.difference % this.msPerYear) / this.msPerMonth) ;
    }

    differenceInWeeks() {
        return Math.floor(((this.difference % this.msPerYear) % this.msPerMonth) / (this.msPerDay * 7));
    }

    differenceInDays() {
        return Math.floor((((this.difference % this.msPerYear) % this.msPerMonth) % (this.msPerDay * 7)) / this.msPerDay);
    }

    differenceInHours() {
        return Math.floor(((((this.difference % this.msPerYear) % this.msPerMonth) % (this.msPerDay * 7)) % this.msPerDay) / this.msPerHour);
    }

    differenceInMinutes() {
        return Math.floor((((((this.difference % this.msPerYear) % this.msPerMonth) % (this.msPerDay * 7)) % this.msPerDay) % this.msPerHour) / this.msPerMinute);
    }

    differenceInSeconds() {
        return Math.floor(((((((this.difference % this.msPerYear) % this.msPerMonth) % (this.msPerDay * 7)) % this.msPerDay) % this.msPerHour) % this.msPerMinute) / 1000);
    }
}

const dateDiff = new DateDifference('2020-01-01', '2022-01-01');
console.log(`${dateDiff.differenceInYears()} years, ${dateDiff.differenceInMonths()} months, ${dateDiff.differenceInWeeks()} weeks, ${dateDiff.differenceInDays()} days, ${dateDiff.differenceInHours()} hours, ${dateDiff.differenceInMinutes()} minutes, ${dateDiff.differenceInSeconds()} seconds`);
```

This code snippet will return the amount of years, months, weeks, days, hours, minutes and seconds between two dates.

Note: This is a simplification. Precise calculation might require consideration for variable month lengths, leap years, time zones, and daylight saving time changes.

To write an Arduino program that reads analog values from a temperature sensor, we will use the LM35 temperature sensor. This sensor gives an output of 10mV per degree of Celsius. If the temperature is 30 degrees Celsius, the output will be 300mV or 0.3V.

Here is a simple Arduino program that does this:

```cpp
// Define the Analog input pin to be used (connect LM35 to A0)
const int tempSensorPin = A0;

void setup() {
  // Starts the serial communication
  Serial.begin(9600);
}

void loop() {
  // Read the value from the sensor
  float sensorValue = analogRead(tempSensorPin);

  // Convert the analog reading into voltage
  float voltage = sensorValue * (5.0 / 1023.0);

  // Convert the voltage into temperature
  float tempCelsius = voltage * 100;

  // Check if the temperature is greater than 30 degrees Celsius
  if (tempCelsius > 30.0) {
    // Print the temperature to the Serial monitor
    Serial.print("Current Temperature: ");
    Serial.print(tempCelsius);
    Serial.println(" C");
  }

  // Wait for a second before taking the next reading
  delay(1000);
}
```
Important points to notice:

- The code uses the Arduino’s built-in function analogRead() to read the sensor data.
- The formula for converting sensor value into the voltage is obtained considering that Arduino has a built-in 10-bit ADC ranging from 0V to 5V.
- The formula for converting voltage into temperature in degree Celsius is derived from sensor's datasheet.
- In the comparison `if (tempCelsius > 30.0)`, we are checking whether the temperature reading is above 30 degrees Celsius.
- The `Serial.print` and `Serial.println` functions are used to output the temperature to the serial monitor whenever the temperature is over 30 degrees Celsius.

You can upload this code into your Arduino board, using the Arduino IDE. After uploading, open the serial monitor to see temperature readings above 30 degrees Celsius. Make sure the baud rate of the Serial Monitor matches the baud rate specified in your code (9600 in this case).

