export default {
  data() {
    return {
      weather: null,
      error: null,
      longitude: null,
      latitude: null
    };
  },
  methods: {
    async getWeather() {
      if (!navigator.geolocation) {
        this.error = "Geolocation is not supported by your browser.";
      } else {
        try {
          navigator.geolocation.getCurrentPosition(async (position) => {
            this.longitude = position.coords.longitude;
