```python
from gql import gql, Client
from gql.transport.requests import RequestsHTTPTransport
import os
import requests

class GraphqlClient:
    def __init__(self, api_url, headers):
        self.api_url = api_url
        self.headers = headers
        self.transport = RequestsHTTPTransport(
            url=self.api_url,
            headers=self.headers,
            use_json=True,
        )
        self.client = Client(
            retries=3,
            transport=self.transport,
            fetch_schema_from_transport=True,
        )

    def run_query(self, query):
        return self.client.execute(gql(query))


class RubyReleasesClient(GraphqlClient):
    def __init__(self, api_url, headers):
        super().__init__(api_url, headers)

    def get_all_ruby_releases(self):
        end_cursor = ""
        while True:
            query = """
            {
                repository(owner:"ruby", name:"ruby") {
                    releases(first:100, after:"%s") {
                        pageInfo {
                            endCursor
                            hasNextPage
                        }
                        nodes {
                            name
                            publishedAt
                            tag {
                                name
                            }
                        }
                    }
                }
            }
            """ % end_cursor

            try:
                result = self.run_query(query)
                releases = result['repository']['releases']['nodes']
                for release in releases:
                    print(release)

                # Update the cursor
                end_cursor = result['repository']['releases']['pageInfo']['endCursor']

                # Check if there's a next page
                if not result['repository']['releases']['pageInfo']['hasNextPage']:
                    break

            except requests.exceptions.RequestException as e:
                print(f"An error occurred: {e}")


api_url = "https://api.github.com/graphql"
headers = {"Authorization": f"Bearer {os.environ['GITHUB_ACCESS_TOKEN']}"}
client = RubyReleasesClient(api_url, headers)
client.get_all_ruby_releases()
