function generatePascalPyramid(n) {
    const pyramid = [[[1]]];

    for(let layer = 1; layer < n; layer++) {
        pyramid.push([]);
        for(let row = 0; row <= layer; row++) {
            pyramid[layer].push([]);
            for(let col = 0; col <= layer; col++) {
                pyramid[layer][row][col] = (pyramid[layer-1][row] && (pyramid[layer-1][row][col] || 0)
                + pyramid[layer-1][row-1] && (pyramid[layer-1][row-1][col] || 0)
                + pyramid[layer-1][row-1] && (pyramid[layer-1][row-1][col-1] || 0));
