```python
import unittest

class InvalidAliasError(Exception):
    pass

class Avatar:
    def __init__(self, alias):
        self._alias = None
        self.alias = alias

    @property
    def alias(self):
        return self._alias

    @alias.setter
    def alias(self, value):
        #Check that alias value is alphanumeric
        if not value.isalnum():
            raise InvalidAliasError("Alias should only contain alphanumeric characters.")
        #Check that the length of alias value does not exceed 20 characters
        if len(value) > 20:
            raise InvalidAliasError("Alias should not exceed 20 characters in length.")
        self._alias = value

