Here's an algorithm in JavaScript which can take any number and determine if it is a power of two by continuously dividing the number by two and checking if the result is an integer until one is reached:

```js
function isPowerOfTwo(n){
  // Check if the number is less than one. If so, return false
  if (n < 1){
    return false;
  }
  // Otherwise, divide the number by two until the result is less than two
  while (n > 2){
    // If the number is not a whole number, return false 
    if (n % 2 !== 0){
      return false;
    } else {
      // Otherwise, continue dividing the number by two
      n = n / 2;
    }
  }
  // If the loop is exited without returning, that means n is a power of two so return true
  return true;
}

