We can solve the problem by creating a recursive function that deals specifically with nested arrays, including ones containing non-arrays and other objects. Also, we should tackle the issue of circular references using a Map object that keeps track of arrays that have already been processed. Here is the revamped function.

```javascript
const obj = { data: [6, [7,8], 9, {nest: 10, nest2: [11, 12]}] };

function flattenNestedArrays(arr, cache = new Map()) {
    let result = [];

    if (Array.isArray(arr)) {
        if (cache.get(arr)) {
            result.push('[Circular]');
        } else {
            cache.set(arr, true);
            for (let item of arr) {
                if (Array.isArray(item) || (typeof item === 'object' && item !== null)) {
                    result.push(...flattenNestedArrays(item, cache));
                } else {
                    result.push(item);
                }
            }
            cache.delete(arr);
        }
    } else if (typeof arr === 'object' && arr !== null) {
        for (let key in arr) {
            if (Array.isArray(arr[key]) || (typeof arr[key] === 'object' && arr[key] !== null)) {
                result.push(...flattenNestedArrays(arr[key], cache));
            } else {
                result.push(arr[key]);
            }
        }
    } else {
        result.push(arr);
    }

    return result;
}

console.log(flattenNestedArrays(obj.data));
