```java
public class Main {
    public static void main(String[] args) {
        rotateValues(1, 2, 3);
    }

    static void rotateValues(int a, int b, int c){
        System.out.println("Initial values: " + a + ", " + b + ", " + c);

        // Implementing rotary cyclical process
