import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Declare several strings:
        String str1 = "stack";
        String str2 = "overflow";
        String str3 = null;
        String str4 = "";
        System.out.println(getLongest(str1, str2, str3, str4));
    }

    private static String getLongest(String... strings) {
        if (strings == null || strings.length == 0) return null;
        var map = new TreeMap<Integer, List<String>>();
        for (String str : strings) {
            if (str != null && !str.isEmpty()) {
                map.computeIfAbsent(str.length(), k -> new ArrayList<>()).add(str);
            }
        }
        if (map.isEmpty()) return null;
        var entries = map.lastEntry().getValue();
        if (entries.size() > 1) {
            return "存在長度相等的序列: " + String.join(" , ", entries);
        } else {
            return entries.get(0);
        }
    }
}
