Here is a simple C function to calculate the final price:

```c
#include <stdio.h>

float calculate_final_price(float original_price, float service_tax_pct, float concession_pct, float late_fee_pct) {

    // Check for invalid inputs
    if(original_price < 0 || service_tax_pct < 0 || concession_pct < 0 || late_fee_pct < 0 
       || service_tax_pct > 100 || concession_pct > 100 || late_fee_pct > 100) {
        printf("Error: Invalid inputs\n");
        return -1; // Return some error code
    }

    float final_price;

    // Calculate the service tax and add it to the original price
    final_price = original_price + (original_price * (service_tax_pct/100));

    // Subtract the concession from the final price
    final_price = final_price - (final_price * (concession_pct/100));

    // Add the late fee to the final price
    final_price = final_price + (final_price * (late_fee_pct/100));

    return final_price;
}
```
This function accepts four percentages as input parameters, meaning the values are expected to be in the range 0 to 100. If any of the input values is less than 0 or greater than 100, the function will return an error.

Note that this code assumes that the concession is applied after the service tax is added and that the late fee is applied after the concession is subtracted. If the sequence needs to be changed, you can modify the code accordingly.

```ruby
class BookNotFound < StandardError; end
class BookAlreadyBorrowed < StandardError; end

class LibraryBook

  attr_accessor :title, :author, :publication_year, :genre, :edition

  @@book_list = []

  def initialize(title, author, publication_year, genre, edition)
    @title = title
    @author = author
    @publication_year = publication_year
    @genre = genre
    @edition = edition
    @borrowed = false
    @borrower = nil
    @due_date = nil
    @reservations = []
    @history = {}
    @@book_list << self
  end

  def self.find_by_title(title)
    book = @@book_list.find { |book| book.title == title }
    raise BookNotFound, 'Book not found!' unless book
    book
  end

  def self.create(title, author, publication_year, genre, edition)
    new(title, author, publication_year, genre, edition)
  end

  def self.delete(book)
    @@book_list.delete(book)
  end

  def borrow(borrower, due_date)
    raise BookAlreadyBorrowed, 'This book is already borrowed!' if @borrowed
    @borrowed = true
    @borrower = borrower
    @due_date = due_date
    @history[Time.now] = ["Borrowed by #{borrower}", "Due date: #{due_date}"]
  end

  def return_book(borrower)
    @borrowed = false
    @borrower = nil
    @due_date = nil
    @history[Time.now] = ["Returned by #{borrower}"]
  end

  def reserve(borrower)
    @reservations << borrower
    @history[Time.now] = ["Reserved by #{borrower}"]
  end

  def cancel_reservation(borrower)
    @reservations.delete(borrower)
    @history[Time.now] = ["Cancelled reservation by #{borrower}"]
  end

  def history
    @history
  end
end
```

This class `LibraryBook` contains class methods for creating and finding books, and instance methods for borrowing, returning, reserving, and canceling reservations. It also maintains a history log of these actions.

I have also added custom exception handling for scenarios where a book is not found (`BookNotFound`) and a book is already borrowed (`BookAlreadyBorrowed`).

