public class FridaysCalculator {

    public static void main(String[] args) throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat("MM/dd/yyyy");
        Date startDate = sdf.parse("07/01/2021");
        Date endDate = sdf.parse("12/31/2021");

        printFridays(startDate, endDate);
    }

    private static void printFridays(Date startDate, Date endDate) {
