        cal.setTime(startDate);
        while (!cal.getTime().after(endDate)) {
            if (cal.get(Calendar.DAY_OF_WEEK) == Calendar.FRIDAY) {
                System.out.println(new SimpleDateFormat("MM/dd/yyyy").format((cal.getTime())));
            }
            cal.add(Calendar.DATE, 1);
        }
    }
}
