//First, we will design the structure of a binary tree node 
struct TreeNode<Type> {
    data: Type,
    left: Option<Box<TreeNode<Type>>>,
    right: Option<Box<TreeNode<Type>>>,
}

//Now, we are going to implement the BST functionality
impl<Type: Ord> TreeNode<Type> {

    //This function will help to validate if a tree is a binary search tree
    fn is_bst(&self) -> bool {
        self.is_bst_helper( None, None )
    }

    fn is_bst_helper(&self, lower_limit: Option<&Type>, upper_limit: Option<&Type>) -> bool {
        if let Some(ref lower_limit) = lower_limit {
            if self.data <= *lower_limit {
                return false; 
            } 
        }

        if let Some(ref upper_limit) = upper_limit {
            if self.data >= *upper_limit {
                return false;
            }
        }

        let left_bst = if let Some(ref left_boxed_tree) = self.left {
            left_boxed_tree.is_bst_helper( lower_limit, Some(&self.data) )
        }
        else {
            true
        };

        let right_bst = if let Some(ref right_boxed_tree) = self.right {
            right_boxed_tree.is_bst_helper( Some(&self.data), upper_limit )
        }
        else {
            true
        };

        left_bst && right_bst
    }

    // Recursive implementation of finding the lowest common ancestor
    fn recursive_lca(&self, node1: &Type, node2: &Type) -> Option<&Type> {
        if self.data > *node1 && self.data > *node2 {
            self.left.as_ref()?.recursive_lca(node1, node2)
        } else if self.data < *node1 && self.data < *node2 {
            self.right.as_ref()?.recursive_lca(node1, node2)
        } else {
            Some(&self.data)
        }
    }

    // Iterative implementation of finding the lowest common ancestor
    fn iterative_lca(&self, node1: &Type, node2: &Type) -> Option<&Type> {
        let mut current_node = self;

        while let Some(current_data) = Some(&current_node.data) {
            if *current_data > *node1 && *current_data > *node2 {
                current_node = current_node.left.as_ref()?;
            } else if *current_data < *node1 && *current_data < *node2 {
                current_node = current_node.right.as_ref()?;
            } else {
                return Some(current_data);
            }
        }

        None
    }
}
```

