```javascript
function validateCardNumber(number) {
  let cardNumber = number.toString();
  let length = cardNumber.length;
  let parity = length % 2;
  let sum = 0;

  for(let i = 0; i < length; i++) {
    let digit = parseInt(cardNumber.charAt(i));

    if(i % 2 == parity) 
      digit *= 2;

    if(digit > 9) 
      digit -= 9;

    sum += digit;
  } 

  return sum % 10 == 0;
}
```
