```Java
public class Matrix3D {

    private final int[][][] matrix;

    public Matrix3D(int num1, int num2, int num3) {
        matrix = new int[num1][num2][num3];
        for (int i = 0; i < num1; i++) {
            for (int j = 0; j < num2; j++) {
                for (int k = 0; k < num3; k++) {
                    matrix[i][j][k] = (i + 1) * (j + 1) * (k + 1);
                }
            }
        }
    }

    public int add(int x, int y, int z, int value) {
        return matrix[x][y][z] += value;
    }

    public int subtract(int x, int y, int z, int value) {
        return matrix[x][y][z] -= value;
    }

    public int multiply(int x, int y, int z, int value) {
        return matrix[x][y][z] *= value;
    }

    public int divide(int x, int y, int z, int value) {
        if (value != 0) {
            return matrix[x][y][z] /= value;
        } else {
            throw new ArithmeticException("Cannot divide by zero");
        }
    }

    public void display() {
        for (int[][] matrix1 : matrix) {
            for (int[] matrix2 : matrix1) {
                for (int i : matrix2) {
                    System.out.print(i + "\t");
                }
                System.out.println();
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        Matrix3D matrix3D = new Matrix3D(8, 10, 12);
        matrix3D.display();
        System.out.println("After arithmetic operations:");
        matrix3D.add(4, 5, 6, 2);
        matrix3D.subtract(2, 3, 4, 1);
        matrix3D.multiply(1, 2, 3, 3);
        matrix3D.divide(5, 6, 7, 4);
        matrix3D.display();
    }
}
```

