    var transposedMatrix: [[Double]] = Array(repeating: Array(repeating: 0.0, count: matrix.count), count: matrix[0].count)
    for i in 0..<matrix.count {
        for j in 0..<matrix[i].count {
            transposedMatrix[j][i] = matrix[i][j]
