def find_common_elements(data1, data2):
    common_pairs = []
    for i in range(len(data1)):
        for j in range(len(data2)):
            if data1[i] == data2[j]:
                common_pairs.append((i, j))
    return common_pairs

def find_pattern(common_pairs):
    diffs = []
    for i in range(1, len(common_pairs)):
        diffs.append((common_pairs[i][0] - common_pairs[i-1][0], common_pairs[i][1] - common_pairs[i-1][1]))

    if len(set(diffs)) > 1:
        return "No consistent pattern"
    else:
        return "Consistent pattern found", diffs[0]
