    return sys.getsizeof(i)

def sample(p, q, r):
    # Type checking
    if not all([isinstance(i, (int, float)) for i in [p, q, r]]):
        raise ValueError("Inputs should be numerical values.")

    # Mathematical operations
    n = p - q - r  # subtraction
    if isinstance(n, int): print(f"Variable 'n' is of {type(n)} and uses {get_mem_size(n)} bytes.")
    else: raise TypeError("Subtraction operation resulted in non-numerical value.")

