        raise ZeroDivisionError("Modulus not defined for denominator zero.")

    if isinstance(m, int): print(f"Variable 'n' is of {type(m)} and uses {get_mem_size(m)} bytes.")
    else: raise TypeError("Modulus operation resulted in non-numerical value.")

    o = n * m  # multiplication
    if isinstance(o, int): print(f"Variable 'n' is of {type(o)} and uses {get_mem_size(o)} bytes.")
    else: raise TypeError("Multiplication operation resulted in non-numerical value.")

    return n, m, o

# Test cases
