#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <fstream>
#include <cmath>
#include <mutex>

std::mutex mtx;
std::vector<unsigned long long int> primes;

bool isPrime(unsigned long long n){
  if(n <= 1) 
    return false;
  unsigned long long int sqrtVal = sqrt(n);
  for (unsigned long long int i=2; i<= sqrtVal; i++)
     if (n%i == 0)
         return false; 
  return true;
}

void findPrimes(unsigned long long lLimit, unsigned long long uLimit){
    for(unsigned long long i=lLimit; i<=uLimit; i++){
        if(isPrime(i)){
            mtx.lock();
            primes.push_back(i);
            mtx.unlock(); 
        }
    } 
}

int main(){
    unsigned long long lowLimit = 2;
    unsigned long long upperLimit = 1e12;
    int numThreads = std::thread::hardware_concurrency();
    unsigned long long partitionSize = (upperLimit - lowLimit) / numThreads;

    std::vector<std::thread> threads;
    for(int i=0; i<numThreads; i++){
        threads.push_back(std::thread(findPrimes, lowLimit + i*partitionSize, lowLimit + (i+1)*partitionSize - 1));
    }
    for(auto& th : threads){
        th.join();
    }

    for(unsigned long long p: primes){
        std::cout << p << " ";
    }

