def advanced_bracket_sequence(arr):
    '''
    Accepting an array of minimum two singular strings containing only open parentheses '(',
    closing parentheses ')', open curly braces '{' and closing curly braces '}'. 
    The function ought to determine if a possible concatenation sequence exists, 
    that when assembled results in a string with accurately nested brackets. 
    For example, '(()){}' is a valid sequence, while '()){)' isn't.
    The function returns 'Yes' for a possible sequence, or 'No' otherwise.

    Examples:
    advanced_bracket_sequence(['(', ')(){', '((']) == 'Yes'
    advanced_bracket_sequence([')', ')', '(', '{', '}', '(', '{']) == 'No'
    '''
    bracket_types = {'(': ')', '{': '}'}
    open_brackets, closed_brackets = [], []

    for cell in arr:
        for char in cell:
            if char in bracket_types:
                open_brackets.append(char)
            else:
                if len(open_brackets) == 0:
                    return 'No'
                else:
                    if bracket_types[open_brackets[-1]] == char:
                        open_brackets.pop()
                    else:
                        return 'No'

    if len(open_brackets) > 0:
        return 'No'

    return 'Yes'
