function rgbToHex(rgbArray) {
    // validate rgb array
    if(rgbArray.every(rgb => Array.isArray(rgb) && rgb.length === 3 && rgb.every(val => typeof val === 'number' && val >= 0 && val <= 255))) {
        return rgbArray.map(([r, g, b]) => '#' + (r << 16 | g << 8 | b).toString(16).padStart(6, '0'));
