Here is a python solution:

```Python
import datetime

def is_valid_year(year):
    """Validate if a year is within the range 1900-2100."""
    if year < 1900 or year > 2100:
        return False
    return True

def is_valid_day(day, year):
    """Validate if a day is within the range 1-365 or 1-366 for a leap year."""
    if year%4 == 0 and (year%100 != 0 or year%400 == 0):  # Leap year
        if day < 1 or day > 366:
            return False
    else:
        if day < 1 or day > 365:
            return False
    return True

def convert_day_to_date(day, year):
    """Convert a day of the year into its corresponding date."""
    if not is_valid_day(day, year) or not is_valid_year(year):
        return 'Invalid day or year'
    date = datetime.datetime(year, 1, 1) + datetime.timedelta(day-1)
    return date.strftime('%d-%b-%Y').upper()

def convert_date_to_day(date):
    """Convert a date back into the day of the year format."""
    try:
        date = datetime.datetime.strptime(date, '%d-%b-%Y')
    except ValueError:
        return 'Invalid date format'
    year = date.year
    if not is_valid_year(year):
        return 'Invalid year'
    day = (date - datetime.datetime(year, 1, 1)).days + 1
    return day


print(convert_day_to_date(200, 2020))  # 18-JUL-2020
print(convert_date_to_day('18-JUL-2020'))  # 200
```

In these two functions, `convert_day_to_date(day, year)` takes parameters a `day` of the year (1-366) and a `year` (1900-2100), and `convert_date_to_day(date)` takes a `date` parameter in the DD-MMM-YYYY format. Appropriate checks for leap years, date formats and date ranges have been added.

