Here's a sample function that does this:

```javascript
function presentValue(transactions, periodsPerYear = 1) {
    let result = 0.0; 
    for(let i = 0; i < transactions.length; i++) {
        let transaction = transactions[i];
        let FV = transaction.futureValue || 0; 
        let r = transaction.interestRate || 0; 
        let delay = transaction.delay || 0;
        let penalty = transaction.penalty || 0; 
        let inflation = transaction.inflation || 0;
        let t = i + 1 + delay; // +1 to capture the initial period, +delay for late payments

        let nominalRate = (r / periodsPerYear - inflation) * t + penalty;
        result += FV / Math.pow(1 + nominalRate, periodsPerYear * t)
    }
    return result;
}

// usage example:
