from scipy.stats import hmean, gmean

def model_eval_metric(y_true, y_pred, metric='mse', average='arithmetic'):
    if metric == 'mse':
        result = mean_squared_error(y_true, y_pred)
    elif metric == 'r2':
        result = r2_score(y_true, y_pred)
    else:
        raise ValueError(f"Unknown metric: {metric}")

    if average == 'arithmetic':
        return result
    elif average == 'harmonic':
        return hmean([result, result])
    elif average == 'geometric':
        return gmean([result, result])
    elif average == 'quadratic':
        return np.sqrt(np.mean(np.square([result, result])))
    else:
        raise ValueError(f"Unknown average: {average}")

# Test the function
