class Node:
    def __init__(self, id, parent=None):
        self.id = id
        self.parent = parent
        self.children = []

    def add_child(self, child):
        self.children.append(child)
        child.parent = self

    def remove_child(self, child):
        self.children.remove(child)
        child.parent = None

    def find_path(self, other, path=None):
        if path is None:
            path = [self.id]
        if self is other:
            return path
        for child in self.children:
            child_path = child.find_path(other, path + [child.id])
            if child_path is not None:
                return child_path
        return None

    def __repr__(self):
        return f"Node({self.id}, Parent: {self.parent}, Children {self.children})"


