Here is a simple implementation of the doubly linked list in C++:

```cpp
#include<iostream>
using namespace std;

struct Node {
  int data;
  Node* next;
  Node* prev;
};

// Create new node
Node* getNewNode(int data) {
  Node* newNode = new Node();
  newNode->data = data;
  newNode->next = NULL;
  newNode->prev = NULL;
  return newNode;
}

// Insert a node at head
Node* InsertAtHead(Node* head, int data) {
  Node* newNode = getNewNode(data);
  if(head == NULL) {
    head = newNode;
    return head;
  }
  head->prev = newNode;
  newNode->next = head; 
  head = newNode;
  return head;
}

// Insert a node at tail
Node* InsertAtTail(Node* head, int data) {
  Node* temp = head;
  Node* newNode = getNewNode(data);
  if(head == NULL) {
    head = newNode;
    return head;
  }
  while(temp->next != NULL) temp = temp->next; 
  temp->next = newNode;
  newNode->prev = temp;
  return head;
}

// Delete a node
Node* DeleteNode(Node* head, int data) {
  Node* temp = head;
  while(temp != NULL) {
    if(temp->data == data) {
      if(temp->prev != NULL) temp->prev->next = temp->next;
      if(temp->next != NULL) temp->next->prev = temp->prev;
      delete(temp);
      return head;
    }
    temp = temp->next;
  }
  cout << "Node with data " << data << " doesn't exist." << endl;
  return head;
}

// Print the list in forward direction.
void Print(Node* head) {
  Node* temp = head;
  cout << "Forward: ";
  while(temp != NULL) {
    cout << temp->data << " ";
    temp = temp->next;
  }
  cout << "\n";
}

// Print the list in reverse direction.
void ReversePrint(Node* head) {
  Node* temp = head;
  if(temp == NULL) return; // empty list, exit
  while(temp->next != NULL) {
    temp = temp->next; // Going to last node
  }
  cout << "Reverse: ";
  while(temp != NULL) {
    cout << temp->data << " ";
    temp = temp->prev;
  }
  cout << "\n";
}

// Driver code
int main() {
  Node* head = NULL;  
  head = InsertAtTail(head, 2);
  head = InsertAtTail(head, 4);
  head = InsertAtHead(head, 6);
  head = InsertAtTail(head, 8);
  Print(head); 
  ReversePrint(head);
  head = DeleteNode(head, 4);
  Print(head); 
  ReversePrint(head);
} 
```
This code covers the operations on a doubly linked list, like insertion at head/tail, deletion of node, and printing/traversing the list in both directions.

