A perfect number is a positive integer that is equal to the sum of its proper positive divisors, excluding the number itself. A proper divisor is a divisor of a number, excluding the number itself. For instance, 6 is a perfect number because it is divisible by 1, 2, and 3, which also sum up to 6.

Below is a simple C++ program that solves the given problem:

```cpp
#include <iostream>
using namespace std;

bool isPerfect(int num) {
    int sum = 1;
    for(int i=2; i*i<=num; i++) {
        if(num%i==0) {
            if(i*i!=num)
                sum = sum + i + num/i;
            else
                sum = sum + i;
        } 
    } 
    if (sum==num && num!=1)
        return true;

   return false;
}

bool isPrime(int num) {
    if (num <= 1)
        return false;
    if (num <= 3)
        return true;

    if (num%2 == 0 || num%3 == 0)
        return false;

    for (int i=5; i*i<=num; i=i+6)
        if (num%i == 0 || num%(i+2) == 0)
            return false;

    return true;
}

int main() {
    int lowEnd, highEnd;

    cout<<"Please enter the lower limit: ";
    cin>>lowEnd;

    if(!cin){
        cout<<"Wrong input type, please provide an integer.";
        return 0;
    }

    cout<<"Please enter the upper limit: ";
    cin>>highEnd;

    if(!cin){
        cout<<"Wrong input type, please provide an integer.";
        return 0;
    }

    int sum = 0;
    for(int i=lowEnd; i<= highEnd; i++) {
        if(isPerfect(i)) {
            cout << "Number " << i << " is perfect.\n";
            sum += i;
            if(isPrime(i) && (i % 2) != 0)
                cout << "Number " << i << " is also a prime-odd perfect number.\n";
        }
    }

    cout << "Sum of all perfect numbers: " << sum;

    return 0;
}
```
Note: Prime-odd perfect number is not currently known to exist or not, hence the code includes a check for prime and odd perfect numbers.

