def transform_text(s):
    # Assume s is a string
    STACK, PART= [], []
    for c in s:
        if c in ['(', '[', '{']:
            STACK.append((c, "".join(PART)))
            PART = []
        elif c in [')', ']', '}']:
            if STACK and (ord(STACK[-1][0]) - ord(c)) in [-1, -2]:  
                last_parenthesis, last_text = STACK.pop()
                postprocess_text = "".join(PART)
                if last_parenthesis == "(":
                    transformed = " ".join(word[::-1] for word in postprocess_text.split(' '))
                elif last_parenthesis == "[":
