                else:
                    transformed = postprocess_text
                PART = [last_text, " ", transformed]
            else:
                return "Error: unbalanced or incorrectly nested parentheses."
        else:
            # add character to current part
            PART.append(c)

    if STACK:
        return "Error: unbalanced or incorrectly nested parentheses."
    else:
        return "".join(PART).swapcase()

