This problem can be solved with multiple steps as follows: 

1. Convert the two given Binary Search Trees (BSTs) to Doubly Linked Lists (DLLs)
2. Merge the two sorted DLLs into one
3. Convert the merged DLL back to a Balanced BST

Here is the C++ function implementation:

```c++
#include<bits/stdc++.h>
using namespace std;

class node {
public:
    int data;
    node* left, * right;
};

node* newNode(int data) {
    node* Node = new node();
    if (!Node) {
        cout << "Memory error\n";
        return NULL;
    }
    Node->data = data;
    Node->left = Node->right = NULL;
    return Node;
}

node* sortedListToBST(node **head_ref, int n){
    if (n <= 0)
        return NULL;
    node *left = sortedListToBST(head_ref, n/2);
    node *root = *head_ref;
    root->left = left;
    *head_ref = (*head_ref)->right;
    root->right = sortedListToBST(head_ref, n - n / 2 - 1);
    return root;
}

node* mergeDLLs(node* head1, node* head2) {
    if (head1 == NULL)
        return head2;

    if (head2 == NULL)
        return head1;

    if (head1->data < head2->data) {
        head1->right = mergeDLLs(head1->right,head2);
        head1->right->left = head1;
        head1->left = NULL;
        return head1;
    } else {
        head2->right = mergeDLLs(head1, head2->right);
        head2->right->left = head2;
        head2->left = NULL;
        return head2;
    }
}

node* binaryTreeToDLL(node **root_ref) {
    if (*root_ref == NULL)
        return NULL;

    node* a = binaryTreeToDLL(&((*root_ref)->left));
    node* b = binaryTreeToDLL(&((*root_ref)->right));

    (*root_ref)->left = (*root_ref)->right = NULL;

    return mergeDLLs(mergeDLLs(a, *root_ref), b);
}

node* mergeTwoBSTs(node* root1, node* root2) {
    node* head1 = binaryTreeToDLL(&root1);
    node* head2 = binaryTreeToDLL(&root2);
    node* merged = mergeDLLs(head1, head2);

    int n = 0;
    node *temp = merged;
    while (temp){
        n++;
        temp = temp->right;
    }

    return sortedListToBST(&merged, n);
}

void preOrder(node* node) {
    if (node == NULL)
        return;
    cout << node->data << " ";
    preOrder(node->left);
    preOrder(node->right);
}

int main() {
    node* root1 = newNode(3);
    root1->left = newNode(1);
    root1->right = newNode(5);

    node* root2 = newNode(4);
    root2->left = newNode(2);
    root2->right = newNode(6);

    node* mergedTree = mergeTwoBSTs(root1, root2);

    cout << "Merged tree in preorder is \n";
    preOrder(mergedTree);

    return 0;
}
```

Kindly note that there are multiple techniques to convert a Binary Search Tree to a Doubly Linked List (DLL), to merge two DLLs and to convert a DLL to a Balanced Binary Search Tree. This is one of those methods.

