Here is a possible way of implementing a generic selection sort algorithm with the performance stats in C:

```c
#include <stdio.h>
#include <time.h>

// Function prototypes
void selection_sort_int(int* arr, int n, int* comparisons, int* swaps);
void selection_sort_float(float* arr, int n, int* comparisons, int* swaps);

void selection_sort_int(int* arr, int n, int* comparisons, int* swaps) {
    for (int i = 0; i < n - 1 ; i++) {
        int min_index = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_index]) {
                min_index = j;
            }
            (*comparisons)++;
        }
        if (min_index != i) {
            int temp = arr[i];
            arr[i] = arr[min_index];
            arr[min_index] = temp;
            (*swaps)++;
        }
    }
}

void selection_sort_float(float* arr, int n, int* comparisons, int* swaps) {
    for (int i = 0; i < n - 1 ; i++) {
        int min_index = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_index]) {
                min_index = j;
            }
            (*comparisons)++;
        }
        if (min_index != i) {
            float temp = arr[i];
            arr[i] = arr[min_index];
            arr[min_index] = temp;
            (*swaps)++;
        }
    }
}

int main() {
    int nums_int[] = {5, 2, -3, 10, 23, 99, -1, 7, 93, 0};
    float nums_float[] = {5.2, 7.1, -3.6, 10.5, 23.0, 99.1, -1.2, 0.2, 93.7, 0.0};
    int n_int = sizeof(nums_int) / sizeof(nums_int[0]);
    int n_float = sizeof(nums_float) / sizeof(nums_float[0]);
    int comparisons_int = 0, swaps_int = 0;
    int comparisons_float = 0, swaps_float = 0;

    clock_t begin = clock();
    selection_sort_int(nums_int, n_int, &comparisons_int, &swaps_int);
    clock_t end = clock();
    double time_spent_int = (double)(end - begin) / CLOCKS_PER_SEC;

    begin = clock();
    selection_sort_float(nums_float, n_float, &comparisons_float, &swaps_float);
    end = clock();
    double time_spent_float = (double)(end - begin) / CLOCKS_PER_SEC;

    printf("Int array:\n");
    for (int i = 0; i < n_int; i++) {
        printf("%d ", nums_int[i]);
    }
    printf("\nTime: %lf sec, comparisons: %d, swaps: %d\n\n", time_spent_int, comparisons_int, swaps_int);

    printf("Float array:\n");
    for (int i = 0; i < n_float; i++) {
        printf("%f ", nums_float[i]);
    }
    printf("\nTime: %lf sec, comparisons: %d, swaps: %d\n", time_spent_float, comparisons_float, swaps_float);

    return 0;
}
```

This code sorts both arrays using selection sort algorithm separately, measures the time taken, number of comparisons and swaps during sorting. The time measurement was done using the `clock()` function from the standard C library. Note that this measures the CPU time, which might be slightly different from the real time.
The number of comparisons and swaps are incremented each time a comparison or swap is made during the selection sort algorithm. The results are then printed in a readable format.

