    public int digits(int n) {
        // Turning the int `n` into an array of its digits
        String temp = Integer.toString(n);
        int[] newArray = new int[temp.length()];
        for (int i = 0; i < temp.length(); i++) {
            newArray[i] = temp.charAt(i) - '0';
        }

        int product = 1;
        boolean flag = false;

