```python
import requests
import json
import xml.etree.ElementTree as ET

def xml_to_json(url):
    """
    Input: url containing the XML data
    Output: Converted JSON file
    """

    # Request the XML document
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raise exception if invalid response
    except requests.exceptions.RequestException as e:
        print(f"Request Exception: {e}")
        return

    # Parse the XML document
    try:
        root = ET.fromstring(response.content)
    except ET.ElementTree.ParseError as e:
        print(f"Parse Error: {e}")
        return

    # Convert the XML to a Python Dictionary
    def etree_to_dict(t):
        d = {t.tag: {} if t.attrib else None}
        children = list(t)
        if children:
            dd = defaultdict(list)
            for dc in map(etree_to_dict, children):
                for k, v in dc.items():
                    dd[k].append(v)
            d = {t.tag: {k: v[0] if len(v) == 1 else v for k, v in dd.items()}}
        if t.attrib:
            d[t.tag].update(('@' + k, v) for k, v in t.attrib.items())
        if t.text:
            text = t.text.strip()
            if children or t.attrib:
                if text:
                    d[t.tag]['#text'] = text
            else:
                d[t.tag] = text
        return d

    result_dict = etree_to_dict(root)

    # Convert the dictionary to a JSON object and write it to a file
    try:
        with open('output.json', 'w') as f:
            json.dump(result_dict, f)
    except IOError as e:
        print(f"IO Error: {e}")
    except Exception as e:  # Catch all other exceptions
        print(f"Unexpected error: {e}")
    return

# Use the function
xml_to_json('https://example.com/path_to_xml')
```
This Python program retrieves an XML document, converts it to JSON, and saves the result to a file named 'output.json' in the same directory.

