Here is a simple program in C for searching an element in a circular linked list.

```c
#include<stdio.h>
#include<stdlib.h>

struct Node {
    int data;
    struct Node *next;
};


void addNode(struct Node **head_ref, int new_data) {
    struct Node *new_node = (struct Node *)malloc(sizeof(struct Node));
    struct Node *temp = *head_ref;

    new_node->data  = new_data;
    new_node->next = *head_ref;

    if (*head_ref != NULL) {
        while (temp->next != *head_ref)
            temp = temp->next;
        temp->next = new_node;
    } else {
        new_node->next = new_node; 
    }

    *head_ref = new_node;
}

int search(struct Node *head, int item) { 
    struct Node *current = head;
    int index = 0;

    if (head == NULL)
        return -1;

    do {
        if (current->data == item)
            return index;
        current = current->next;
        index++;
    } while(current != head);

    return -1;
}


int main() {
    struct Node *head = NULL;

    addNode(&head, 1);
    addNode(&head, 2);
    addNode(&head, 3);
    addNode(&head, 4);

    int item_to_find = 3;
    int found_index = search(head, item_to_find);

    if(found_index == -1) {
        printf("Item does not exist in the list! \n");
    } else {
        printf("Item found at position: %d\n", found_index);
    }

    return 0;
}
```

This program first creates a circular linked list with 4 nodes. Then, it search for the presence of a number by calling search function. If the function returns -1, it means the number is not present in the list, else the program will print the position of the number in the list.

