Below is a JavaScript function that traverses the DOM tree of a given HTML element and generates text content dictionary:

```javascript
function generateTextContentDictionary(element) {
    let textNodeIndex = 1;
    const textContentDictionary = {};

    function traverseDOMTree(node) {
        for (const childNode of node.childNodes) {
            if (childNode.nodeType === Node.TEXT_NODE && childNode.textContent.trim() !== '') {
                // The node is a non-empty text node
                textContentDictionary['textNode_' + textNodeIndex] = childNode.textContent.trim();
                textNodeIndex++;
            } else if (childNode.nodeType === Node.ELEMENT_NODE) {
                // The node is an element node
                let tag = childNode.tagName.toLowerCase();

                // Checking for empty and self-closing tags
                if (['img', 'br', 'input', 'hr', 'area', 'base', 'link', 'meta', 'param', 'command', 'keygen', 'source'].includes(tag)) {
                    continue;
                } else if (!childNode.firstChild) {
                    continue;
                }

                traverseDOMTree(childNode);
            }
        }
    }

    traverseDOMTree(element);
    return textContentDictionary;
}
```
You can use this function by passing the root element from where you want to start extracting the text content. This function will handle nested elements, empty elements, and self-closing tags. You can combine the text content from elements split into different nodes by modifying the function as needed.

