```cpp
#include <iostream>
#include <fstream>

// recursive function to calculate factorial
long long factorial(int n) {
    if (n > 1)
        return n * factorial(n - 1);
    else
        return 1;
}

// function to write factorials to file
void writeFactorialsToFile(int n, const char * filename) {
    std::ofstream file;
    file.open(filename);

    // check for potential file opening error
    if (!file.is_open()) {
        std::cerr << "Error opening file " << filename << std::endl;
        return;
    }

    for (int i = 1; i <= n; ++i) {
        long long f = factorial(i);
        file << "factorial(" << i << ") = " << f << std::endl;

        // check for potential output error
        if (file.fail()) {
            std::cerr << "Error writing to file " << filename << std::endl;
            file.close();
            return;
        }
    }

    file.close();
}

int main() {
    int n;
    std::cout << "Enter a positive integer: ";
    std::cin >> n;

    // check for potential input error
    if (std::cin.fail() || n <= 0) {
        std::cerr << "Invalid input" << std::endl;
        return -1;
    }

    const char * filename = "factorials.txt";
    writeFactorialsToFile(n, filename);
    std::cout << "Factorials written to " << filename << std::endl;

    return 0;
}
```

This code uses a recursive function to calculate factorials and then another function to write the factorial of every number from 1 to n into a file called "factorials.txt". 
