    int i = 0;
    while (i >= 0) {
        std::cout << "This is loop number: " << i << std::endl;
        // i++ has been removed
    }
    return 0;
}
```

Option 2: resetting "i" in every loop cycle 

```C++
#include<iostream>

int main() {
    int i = 0;
    while (true) { // Changing condition to 'true' so it always performs the loop
        std::cout << "This is loop number: " << i << std::endl;
        i++;
        if(i < 0) // When overflow happens i will become negative
            i = 0; // Reset i to 0
    }
    return 0;
}
```

