Here's the complete code for a version of the Tribonacci sequence based on the provided conditions: This code uses JavaScript.

```javascript
const tri = (n) => {
    // Initialize an array with first two Tribonacci numbers. 
    let triSeq = [3];
    if (n < 0) {
        return 'Input should be a non-negative integer.'
    } else if (n == 0) {
        return triSeq;
    }

    // Getting Tribonacci numbers for even and odd terms
    for(let i = 1; i <= n; i++) {
        if(i % 2 == 0) { 
            // For even terms, tri(n) equals 1 plus half of n
            triSeq.push(1 + (i / 2)); 
        } else {
            // For odd terms, tri(n) equals the sum of: the two preceding terms and the term that follows.
            // Calculate the term that follows (i + 1) first if i is not the last term
            let nextTerm = (i !== n) ? ((i + 1) % 2 == 0 ? 1 + ((i + 1) / 2) : triSeq[triSeq.length - 2] + triSeq[triSeq.length - 1] + triSeq[triSeq.length] + 3) : 0;
            triSeq.push(triSeq[triSeq.length - 2] + triSeq[triSeq.length - 1] + nextTerm);
        }
    }
    return triSeq;
};

console.log(tri(4)); // [3, 1, 5, 2, 12]
```

