```python
class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    def addElement(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            node = self.head
            while node.next:
                node = node.next
            node.next = Node(data)

    def removeElement(self, data):
        if self.head is None:
            return

        if self.head.data == data:
            self.head = self.head.next
            return

        node = self.head
        while node.next:
            if node.next.data == data:
                node.next = node.next.next
                return
            node = node.next

    def getElementByIndex(self, index):
        node = self.head
        for i in range(index):
            if node is None:
                return None
            node = node.next

        if node is not None:
            return node.data
        else:
            return None

    def reverseList(self):
        prev = None
        current = self.head
        while current is not None:
            next_node = current.next
            current.next = prev
            prev = current
            current = next_node
        self.head = prev

    def sortList(self):
        if self.head is None:
            return

        current = self.head
        while current.next:
            next_node = current.next
            while next_node:
                if current.data > next_node.data:
                    current.data, next_node.data = next_node.data, current.data
                next_node = next_node.next
            current = current.next


