Here is a simple outline for a React application that displays a photo album and supports the addition of captions to photos:

```jsx
import React, { Component } from 'react';
import uuid from 'uuid/v4'; // for unique id creation

class AlbumApp extends Component {
  state = {
    photos: [],
    caption: ''
  };

  handleChange = e => {
    this.setState({ caption: e.target.value });
  };

  handleSubmit = e => {
    e.preventDefault();
    if (!this.state.caption) return;
    const newPhoto = { id: uuid(), text: this.state.caption, img: 'DefaultImageUrl' };
    this.setState({
      photos: [...this.state.photos, newPhoto],
      caption: ''
    });
  };

  render() {
    return (
      <div>
        <form onSubmit={this.handleSubmit}>
          <input
            type="text"
            value={this.state.caption}
            onChange={this.handleChange}
          />
          <button>Add</button>
        </form>
        {this.state.photos.map(photo => (
          <div key={photo.id}>
            <img src={photo.img} alt={photo.text} />
            <p>{photo.text}</p>
          </div>
        ))}
      </div>
    );
  }
}

export default AlbumApp;
```

In this code:

1. We're using class-based components. You can easily convert it to functional components and use hooks (`useState`) if you prefer that.
