```python
import re

def phone_number_validation(phone_number):
    pattern = re.compile(r'^(\+\d{1,2}\s?)?1?\-?\.?\s?\(?\d{3}\)?[\-.\s]?\d{3}[\-.\s]?\d{4}$')
    if pattern.match(phone_number):
        return True
    else:
        return False

def extract_geographic_location(phone_number):
    area_code_dict = {
        "212" : "New York",
        "213" : "Los Angeles",
        "312" : "Chicago",
        # Additional area codes go here
    }
    area_code = phone_number[1:4] if phone_number.startswith("1") else phone_number[:3]
    return area_code_dict.get(area_code, "Unknown Location")

phone_number = input("Enter a phone number to validate: ")
