Here is a corrected JavaScript implementation of ternary search:

```javascript
function ternarySearch(givenList, left, right, targetElement, comparator) {
  if (right >= left) {
    let mid1 = Math.floor(left + (right - left) / 3);
    let mid2 = Math.floor(right - (right - left) / 3);

    if (comparator(givenList[mid1], targetElement) === 0) {
      return mid1;
    }
    if (comparator(givenList[mid2], targetElement) === 0) {
      return mid2;
    }

    if (comparator(givenList[mid1], targetElement) > 0) {
      return ternarySearch(givenList, left, mid1-1, targetElement, comparator);
    }
    if (comparator(givenList[mid2], targetElement) < 0) {
      return ternarySearch(givenList, mid2+1, right, targetElement, comparator);
    }
    return ternarySearch(givenList, mid1+1, mid2-1, targetElement, comparator);
  }
  return false;
}
```

Here is also a binary search implementation for comparison:

```javascript
function binarySearch(givenList, left, right, targetElement, comparator) {
  if(right >= left) {
    let mid = Math.floor(left + (right - left) / 2);

    if(comparator(givenList[mid], targetElement) === 0) {
      return mid;
    }

    if(comparator(givenList[mid], targetElement) > 0) {
      return binarySearch(givenList, left, mid - 1, targetElement, comparator);
    }

    return binarySearch(givenList, mid + 1, right, targetElement, comparator);
  }

  return false;
}
```

