Here is a JavaScript solution that returns the largest element of an array, along with its index. It includes the ability to handle nested arrays.

```javascript
function findLargestInArray(arr, arrayIndex = "") {
  let largestNum = -Infinity;
  let index = -1;
  let output = {};

  for (let i = 0; i < arr.length; i++) {
    if (Array.isArray(arr[i])) {
      // Recursively call this function if we found a nested array
      let nestedOutput = findLargestInArray(arr[i], `${arrayIndex}[${i}]`);
      if (nestedOutput.largest > largestNum) {
        largestNum = nestedOutput.largest;
        index = nestedOutput.index;
      }
    } else if (arr[i] > largestNum) {
      largestNum = arr[i];
      index = `${arrayIndex}[${i}]`;
    }
  }

  output.array = arrayIndex;
  output.largest = largestNum;
  output.index = index;

  return output;
}

// Test
console.log(findLargestInArray([21, [22, 23], 24, 25, [26, 27, [28, 29], [1, 2], 13], 17]));
```

