This problem sounds like it requires two primary functions:

1. A function to count the total number of nodes in a binary tree, excluding null values.
2. A function to identify which nodes are prime numbers.

Here's the JavaScript code that should solve the problem:

```javascript
function countNodes(arr) {
    let nodeCount = 0;
    for(let i = 0; i < arr.length; i++) {
        if(arr[i] !== null && Number.isInteger(arr[i])) {
            nodeCount++;
        }
    }
    return nodeCount;
}

function isPrime(num) {
    for(let i = 2; i < num; i++)
        if(num % i === 0) return false;
    return num > 1;
}

function getPrimes(arr) {
    let primes = [];
    for(let i = 0; i < arr.length; i++) {
        if(arr[i] !== null && Number.isInteger(arr[i]) && isPrime(arr[i])) {
            primes.push(arr[i]);
        }
    }
    return primes;
}

let arr = [2, 3, 5, null, 7, 3.14, 8.01, 10, 23];
console.log("Total nodes excluding null and float values: " + countNodes(arr));
console.log("Prime numbers in the binary tree: " + getPrimes(arr));
```

In this code, the `countNodes` function goes through each item in the array and increment the `nodeCount` only if the current item is not null and is an integer. The function `isPrime` checks if a given number is a prime number. The `getPrimes` function uses `isPrime` to identify prime numbers from the array and adds them to another array, `primes`, which gets returned in the end.
Finally, we have a predefined array `arr` which we feed to `countNodes` and `getPrimes` to log the total number of nodes (excluding null and float values) and the array of prime numbers in the binary tree respectively.

