這裡詳細提供了一個使用 JavaScript 來實現該函數的簡單示例。該函數遞歸地訪問每一個屬性，並判斷該屬性的值是否是數字型的。只有當它確定屬性的值是數字型的時候，才將該數字的立方和加入到總數之中。以下為具體的 JavaScript 算法及程式碼：

```javascript
function processNestedNums(obj) {
  let totalSum = 0;

  function processObj(currentObj) {
    for (let key in currentObj) {
      if (typeof currentObj[key] == "number") {
        totalSum += Math.pow(currentObj[key], 3);
      } else if (typeof currentObj[key] == "object" && currentObj[key]!=null) {
        processObj(currentObj[key]);
      }
    }
  }

  processObj(obj);
  return totalSum;
}

const obj = { data: { x: 2, y: 3, z: 4, w: 'text', v: 6, m: { a: 1, b: 2, n: { p: 3 } } } };
console.log(processNestedNums(obj));  // 輸出: 551
```

