import React, { useState } from 'react';

const App = () => {
  const [input, setInput] = useState('');
  const [filteredArray, setFilteredArray] = useState([]);

  const array = [
    {name: 'John', age: 20},
    {name: 'Jane', age: 30},
    {name: 'Jim', age: 40},
  ]

  const handleChange = (event) => {
    setInput(event.target.value);
  }

