```swift
import Foundation

func determinantOf(matrix: [[Int]]) -> Int {
    guard let size = matrix.first?.count, matrix.count == size else { return 0 } // prevents malformed matrices
    switch size {
    case 1: return matrix[0][0]
    case 2: return matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
    default:
        return (0..<size).reduce(0) {
            return $0 + (matrix[0][$1] * cofactor(matrix: matrix, forElementAt: (0, $1)))
        }
    }
}

func cofactor(matrix: [[Int]], forElementAt: (Int, Int)) -> Int {
    return minor(matrix: matrix, forElementAt: forElementAt) * ((forElementAt.0 + forElementAt.1)%2 == 0 ? 1 : -1)
}

func minor(matrix: [[Int]], forElementAt: (Int, Int)) -> Int {
    var subMatrix = matrix
    subMatrix.remove(at: forElementAt.0)
    subMatrix = subMatrix.map { row in
        var mutableRow = row
        mutableRow.remove(at: forElementAt.1)
        return mutableRow
    }
    return determinantOf(matrix: subMatrix)
}

let myMatrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
print("Matrix:")
for line in myMatrix {
    print(line)
}
print("\nDeterminant: \(determinantOf(matrix: myMatrix))")
```

In this code, we first check for the order of the matrix and return 0 if it is not well formed. For 1x1 and 2x2 matrix, determinant is calculated directly. For matrix of order above 3, we use the concept of cofactor. For each element in the top row, we calculate its cofactor and add it to a running total. This total is the determinant of the matrix. The cofactor of an element is the product of -1 raised to the sum of its indexes and the determinant of a sub-matrix formed by eliminating the row and column of the said element.
Please note that determinant calculation for a matrix of order more than 3 can be expensive operation.

