```python
def dec_to_ter(n):
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n == 0:
        return '0'
    nums = []
    negative = False
    if n < 0:
        negative = True
        n = -n 
    while n:
        n, r = divmod(n, 3)
        nums.append(str(r))
