Here is the solution for the problem implemented in C++:

```cpp
vector<int> sort_fifth(vector<int> m){
    // Build a separate vector with multiples of 5th position
    vector<int> c;
    for (int i = 4; i < m.size(); i += 5)
        c.push_back(m[i]);

    // Sort the separate vector
    sort(c.begin(), c.end());

    // Replace multiples of 5th position in original array with sorted numbers
    int j = 0;
    for (int i = 4; i < m.size(); i += 5)
        m[i] = c[j++];

    return m;
};
