```swift
func formatPhoneNumber(_ number: String) -> String {
    var cleanNumber = number.components(separatedBy: CharacterSet.decimalDigits.inverted).joined()
    let length = cleanNumber.count
    if length > 10 {
        let index = cleanNumber.index(cleanNumber.startIndex, offsetBy: length-10)
        cleanNumber = String(cleanNumber[index...])
    }
    let range = NSRange(location: 0, length: cleanNumber.count)
    let pattern = "(\\d{3})(\\d{3})(\\d{4})"
    let regex = try? NSRegularExpression(pattern: pattern)
    let formattedNumber = regex?.stringByReplacingMatches(in: cleanNumber, options: [], range: range, withTemplate: "($1) $2-$3")

    if let output = formattedNumber {
        return output
    } else {
        return cleanNumber
    }
}

