fn fibonacci(n: u32) -> u32 {
    let mut a = 0;
    let mut b = 1;

    match n {
        0 => a,
        _ => {
            for _ in 1..n {
                let temp = a;
                a = b;
                b = temp + b;
            }
            b
        }
