  else if(patternType.toLowerCase() === 'isosceles pyramid') {
    for(let i=0; i<size; i++) {
      pattern += ' '.repeat(size-i-1) + '*'.repeat(i*2+1) + '\n';
    }
  }

  else if(patternType.toLowerCase() === 'diamond') {
    for(let i=0; i<size; i++) {
      pattern += ' '.repeat(size-i-1) + '*'.repeat(i*2+1) + '\n';
    }
    for(let i=size-2; i>=0; i--) {
