const splitWords = (txt) => {
  let vowels = ['a', 'e', 'i', 'o', 'u'];
  txt = txt.toLowerCase();
  let words = txt.includes(' ') ? txt.split(' ') : (txt.includes(',') ? txt.split(',') : null);

  if (words) {
    return words;
  }

  let count = 0;
  for (let i = 0; i < txt.length; i++) {
    if (i % 2 == 1 && txt[i] >= 'a' && txt[i] <= 'z') {
      count++;
    }
  }

  let vowelStr = '';
  for (let i = 0; i < txt.length; i++) {
    if (vowels.includes(txt[i])) {
      vowelStr += txt[i];
    }
  }
  vowelStr = vowelStr.split('').sort().join('');
  let regex = new RegExp('^[aeiou]+$');

  return (regex.test(vowelStr)) ? count : 0;
}

