Here is a Python solution using an `Enum` for the state and a class for the vending machine. Note: this is a simplified solution for readability.

```python
from enum import Enum
import datetime

class State(Enum):
    READY = 1
    AWAITING_PAYMENT = 2

class Product:
    def __init__(self, name, price, quantity):
        self.name = name
        self.price = price
        self.quantity = quantity
        self.sales = []

class VendingMachine:
    def __init__(self, products):
        self.state = State.READY
        self.selected_product = None
        self.money_received = 0
        self.products = {p.name: p for p in products}

    def select_product(self, product_name):
        if self.products[product_name].quantity > 0:
            self.selected_product = self.products[product_name]
            self.state = State.AWAITING_PAYMENT
        else:
            return f"{product_name} is out of stock"

    def insert_money(self, amount):
        if self.state == State.AWAITING_PAYMENT:
            self.money_received += amount
            if self.money_received > self.selected_product.price:
                change = self.money_received - self.selected_product.price
                self.vend_product()
                return f'Here is your {self.selected_product.name} and your change: {change}'
            elif self.money_received == self.selected_product.price:
                return self.vend_product()
            else:
                return f'Please insert {self.selected_product.price - self.money_received} more'
        else:
            return 'No product selected'

    def vend_product(self):
        self.state = State.READY
        self.selected_product.quantity -= 1
        self.selected_product.sales.append([str(datetime.datetime.now()), self.selected_product.price])
        self.money_received = 0
        return f'Here is your {self.selected_product.name}'

    # maintenance mode methods
    def refill_products(self, product_name, quantity):
        self.products[product_name].quantity += quantity

    def change_product_price(self, product_name, new_price):
        self.products[product_name].price = new_price

    def get_sales_data(self, product_name):
        return self.products[product_name].sales
