```python
class ComputedGrammar:
    def __init__(self):
        self.result = ""
        self.count = 0

    def generateCFG(self, regex):
        if regex == '' or regex == 'ɛ':
            return 'S -> ɛ'

        self.result += 'S -> '

        for character in regex:
            if character == '|' or character == '*':
                self.result += 'T' + str(self.count) + ' -> '
                self.count += 1

            self.result += character + ' -> '

        return self.result.rstrip(' -> ')


def main():
    parser = ComputedGrammar()
    regex = input("Please Enter the Regular Expression: ")
    print(parser.generateCFG(regex))


if __name__ == '__main__':
    main()
```
