```javascript
function rollDice() {
  // Math.floor(Math.random() * 6) generates a number between 0 and 5.
  // By adding 1, we get a number between 1 and 6.
  return Math.floor(Math.random() * 6) + 1;
}

function rollMultipleDices(diceCount) {
  if (diceCount < 1) throw new Error("Cannot roll less than one dice");
  let results = [];
  for (let i = 0; i < diceCount; i++) {
    results.push(rollDice());
  }
  return results;
}

function calcDiceRollStats(diceArray) {
  if (diceArray.length === 0) throw new Error("Dice roll array is empty");
  let sum = diceArray.reduce((sum, n) => sum + n, 0);
  let avg = sum / diceArray.length;

  // tally up the instances of each number
  let counts = {};
  for (let i = 0; i < diceArray.length; i++) {
    if (!counts[diceArray[i]]) counts[diceArray[i]] = 0;
    counts[diceArray[i]] += 1;
  }

  let minCount = Infinity, minNum = Infinity, maxCount = -Infinity, maxNum = -Infinity;
  for (let num in counts) {
    if (counts[num] < minCount) {
      minCount = counts[num];
      minNum = Number(num);
    }
    if (counts[num] > maxCount) {
      maxCount = counts[num];
      maxNum = Number(num);
    }
  }

  return {sum: sum, avg: avg, mostFrequent: maxNum, leastFrequent: minNum};
}
```

Both `rollDice` and `rollMultipleDices` functions throw an error if provided with invalid input (less than 1). In the `calcDiceRollStats` function, it first checks if the `diceArray` is empty. After that, it calculates the sum and average of the roll results, then tallies the number counts to find the most and least frequently rolled numbers. For each, it checks if the count is less than `minCount` or greater than `maxCount`, and if it is, the function updates the associated number and count.

