```

JavaScript (app.js):

```javascript
(function () {
    var cache = {};  // cache object to hold click count
    var clickCount;

    function onClickHandler(callback) {
        // click event handler
        return function (id) {
            try {
                // check if the count exists in cache
                if (cache[id]) {
                    clickCount = cache[id];  
                } else {
                   // if not, initialize it
                   clickCount = cache[id] = 0; 
                }

                // increment the count and update cache
                cache[id]++;
                // call the callback function with current count
                callback(clickCount);
            } catch (err) {
                // handle or log any error occurred during click handling
                console.error('Error during click handling.', err);
            }
        } 
    }

    // get button and paragraph elements
    var button = document.getElementById('clickButton');
    var countElement = document.getElementById('clickCount');

    // define a callback that updates UI
    var displayCount = function (count) {
        countElement.innerText = 'Number of clicks: ' + count;
    };

    // attach click event listener
    button.addEventListener('click', onClickHandler(displayCount).bind(null, button.id));
}());
```

In this code, we embedded a counter function in the event handler function that encloses a callback function. The counter function utilizes a cache object to memoize the click count for any given button id. An error handling mechanism is in place through the use of a try-catch block. The displayCount function gets invoked as a callback to display the current click count in the UI.

