```javascript
function reverseVowels(str) {
    let vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
    let strArr = Array.from(str);
    let vowelArr = strArr.filter(letter => vowels.includes(letter));

