        List<Integer> maxIndices = new ArrayList<Integer>();
        int maxValue = arr[0];
        int sumOfIndices = 0;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > maxValue) {
                maxValue = arr[i];
                maxIndices.clear();
                maxIndices.add(i);
            } else if (arr[i] == maxValue) {
                maxIndices.add(i);
            }
        }

        for (int index : maxIndices) {
            sumOfIndices += index;
        }

        System.out.println("Maximum value: " + maxValue);
        System.out.println("Indexes: " + maxIndices);
        System.out.println("Sum of indexes: " + sumOfIndices);
    }
}
