以下是一個簡單的C ++程序，可以用來計算八面體的體積和表面積。在這個程序中，我們假設八面體的每個側面都是等長的。

```cpp
#include <iostream>
#include <cmath>
using namespace std;

// Function to calculate Volume of Octahedron
double calcVolume(double side) {
    return (side * side * side) * sqrt(2) / 3;
}

// Function to calculate Surface Area of Octahedron
double calcSurfaceArea(double side) {
    return 2 * sqrt(2) * side * side;
}

int main() {
    double side;

    cout << "Enter the length of side of the Octahedron: ";
    cin >> side;

    double volume = calcVolume(side);
    double surfaceArea = calcSurfaceArea(side);

    cout << "Volume of the Octahedron is : " << volume << endl;
    cout << "Surface Area of the Octahedron is : " << surfaceArea << endl;

    return 0;
}
