import java.util.Arrays;
import java.util.Random;
import java.util.HashSet;

public class Main {

    public static void main(String[] args) throws Exception {
        // Generate random matrix
        int[][] matrix = generateMatrix(20, 20);

        // Bubble sort the matrix in ascending and descending order
        sortMatrix(matrix, true);
        sortMatrix(matrix, false);
    }

    public static int[][] generateMatrix(int rows, int cols) throws Exception {
        Random rand = new Random();
        int[][] matrix = new int[rows][cols];
        HashSet<Integer> set = new HashSet<>();

        for (int i = 0; i < rows; i++) {
            set.clear();
            for (int j = 0; j < cols; j++) {
                int num = rand.nextInt(101) - 50; // generate numbers from -50 to 50
                if(set.contains(num)){ 
                    throw new Exception("Duplicate number found: " + num); // if duplicate then throw exception
                }
                set.add(num);
                matrix[i][j] = num;
            }
        }
        return matrix;
    }

    public static void sortMatrix(int[][] matrix, boolean ascending) {
        int n = matrix[0].length;
        for (int[] row : matrix) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n - i - 1; j++) {
                    if ((ascending && row[j] > row[j + 1])
                            || (!ascending && row[j] < row[j + 1])) {
                        // swap arr[j] and arr[j+1]
                        int temp = row[j];
                        row[j] = row[j + 1];
                        row[j + 1] = temp;
                    }
                }
            }
        }

        // print the sorted matrix
        System.out.println(ascending ? "Sorted in ascending order:" : "Sorted in descending order:");
        for (int[] row : matrix) {
            System.out.println(Arrays.toString(row));
        }
    }
}
```

