```javascript
function calculateMedians(arrayOfTemperatures) {
    let weeklyMedians = [];
    let allTemperatures = [];

    for(let i = 0; i < arrayOfTemperatures.length; i++) {
        let week = arrayOfTemperatures[i];

        if (!Array.isArray(week) || week.length === 0) {
            throw new Error(`Week ${i} is not a valid array.`)
        }

        week.sort((a, b) => a - b);
        var weekMedian = calculateMedian(week);
        weeklyMedians.push(weekMedian);

        allTemperatures = [...allTemperatures, ...week];
    }

    allTemperatures.sort((a, b) => a - b);
    let overallMedian = calculateMedian(allTemperatures);

    return {overallMedian, weeklyMedians};
}

function calculateMedian(arr) {
    var half = Math.floor(arr.length/2);

    if(arr.length % 2)
        return arr[half];
    else
        return (arr[half-1] + arr[half]) / 2.0;
}

// Test the function:
