import java.util.*;

public class ArrayStats {

    private int[] data;

    public ArrayStats(int[] data) {

        for (Object o : data) {
            if (!(o instanceof Integer)) throw new IllegalArgumentException("All elements in array must be integers");
        }
        this.data = data;
    }

    public double findMean() {
        int sum = 0;
        for (int i : data) {
            sum += i;
        }
        return (double) sum / data.length;
    }

    public double findMedian() {
        Arrays.sort(data);
        if (data.length % 2 != 0) {
            return (double) data[data.length / 2];
        }
        return (double) (data[(data.length - 1) / 2] + data[data.length / 2]) / 2.0;
    }

    public ArrayList<Integer> findMode() {
        HashMap<Integer, Integer> freqMap = new HashMap<Integer, Integer>();
        for (int i : data) {
            if (!freqMap.containsKey(i)) freqMap.put(i, 1);
            else freqMap.put(i, freqMap.get(i) + 1);
        }

        ArrayList<Integer> mode = new ArrayList<Integer>();
        int maxCount = 0;
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mode.clear();
                mode.add(entry.getKey());
            } else if (entry.getValue() == maxCount) {
                mode.add(entry.getKey());
            }
        }
        if(maxCount == 1){
            mode.clear();
        }
        return mode;
    }
}
