    removeDuplicates: function(arr) {
        let result = [];
        for(let i = 0; i < arr.length; i++) {
            if(result.indexOf(arr[i]) === -1) {
              result.push(arr[i]);
            }
        }
        return result;
    },
    performAll: function(arr1, arr2) {
        let arr = this.concatenate(arr1, arr2);
        arr = this.sortAscending(arr);
        arr = this.removeDuplicates(arr);
        return arr;
    }
};

