    let len = arr.length;
    let swapped;
    do {
        swapped = false;
        for (let i = 0; i < len; i++) {
            if (arr[i] < arr[i + 1]) {
                let temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = true;
            }
        }
    } while (swapped);
    return arr;
};

// Testing the function
console.log(bubbleSortDescending([5, 3, 8, 4, 6])); // Outputs: [8, 6, 5, 4, 3]
```
This implementation of bubble sort uses a flag `swapped` to identify if a swap has happened in the current pass. If no swap was made in the current pass, it means the array is already sorted and thus avoids unnecessary comparison in the subsequent passes thereby optimizing the algorithm. This version of bubble sort is slightly better than the traditional approach which lacks this optimization.

However, remember that even with this enhancement, bubble sort is generally not suitable for large datasets as its average and worst-case complexity are both O(n²) where n is the number of items being sorted. For large scale sortings, algorithms like QuickSort, MergeSort or HeapSort are generally preferred.

