你可以把以上代码重新封装到一个函数里，并添加错误处理和超时控制的功能：

```javascript
function ajaxFetch(url, timeout = 5000) {
    return new Promise((resolve, reject) => {
        // 设置超时处理
        const timer = setTimeout(() => {
            reject(new Error(`Fetch timeout: ${url}`));
        }, timeout);

        // 发起请求
        fetch(url)
            .then(response => {
                if (!response.ok) { // 请求失败
                    throw new Error(`Fetch error: ${url}`);
                }
                return response.json();  // 解析 JSON 数据
            })
            .then(data => {   // 成功获取到 JSON 数据
                clearTimeout(timer);
                resolve(data);
            })
            .catch(error => {  // 发生异常
                clearTimeout(timer);
                reject(error);
            });
    });
}

// 使用方式
ajaxFetch('https://api.example.com/data', 10000)
  .then(data => console.log(data))
  .catch(error => console.error('Error:', error));
```

这个 `ajaxFetch` 函数对原生的 Fetch API 做了一层封装，接受一个URL和一个超时时长（默认为5秒，可以调整），然后返回一个 Promise，当 AJAX 请求成功并解析到 JSON 数据，或者超时，或者出现其他异常时，都会 Resolve 或 Reject 这个 Promise。

