def decimal_to_ternary(start, end):
    ternary_dict = {}
    for decimal in range(start, end + 1):
        if decimal == 0:
            ternary_dict[0] = '0'
        else:
            ternary = ''
            while decimal > 0:
                ternary = str(decimal % 3) + ternary
                decimal //= 3
            ternary_dict[decimal] = ternary

    return ternary_dict
```

