A doubly linked list is a sequence of nodes in which every node is connected to its adjacent predecessor and successor nodes. Here is a simple but sophisticated implementation of a doubly linked list in C++. 

```cpp
#include<iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node* prev;
};

//Adding a node at the front of the list
void push(Node** head_ref, int new_data)
{
    Node* new_node = new Node();
    new_node->data = new_data;
    new_node->next = (*head_ref);
    new_node->prev = NULL;
    if ((*head_ref) != NULL)
        (*head_ref)->prev = new_node;
    (*head_ref) = new_node;
}

//Adding a node after a certain node
void insertAfter(Node* prev_node, int new_data)
{
    if (prev_node == NULL) {
        cout<<"the given node cannot be NULL";
        return;
    }
    Node* new_node = new Node();
    new_node->data = new_data;
    new_node->next = prev_node->next;
    prev_node->next = new_node;
    new_node->prev = prev_node;
    if (new_node->next != NULL)
        new_node->next->prev = new_node;
}

//Adding a node at the end of the list
void append(Node** head_ref, int new_data)
{
    Node* new_node =  new Node();
    Node* last = *head_ref;
    new_node->data = new_data;
    new_node->next = NULL;
    if (*head_ref == NULL)
    {
        new_node->prev = NULL;
        *head_ref = new_node;
        return;
    }
    while (last->next != NULL)
        last = last->next;
    last->next = new_node;
    new_node->prev = last;
}

//Deleting a node in a Doubly Linked List
void deleteNode(Node **head_ref, Node *del)
{
    if (*head_ref == NULL || del == NULL)
        return;
    if (*head_ref == del)
        *head_ref = del->next;
    if (del->next != NULL)
        del->next->prev = del->prev;
    if (del->prev != NULL)
        del->prev->next = del->next;
    free(del);
    return;
}

//Display the list
void display(Node* node)
{
    Node* last = new Node();
    while (node != NULL)
    {
        cout << node->data <<  " ";
        last = node;
        node = node->next;
    }
    if(last != NULL)
    {
        cout << "\nTraversal in reverse direction" << endl;
        while (last != NULL)
        {
            cout << last->data << " ";
            last = last->prev;
        }
    }
}

int main()
{
    Node* head = NULL;

    append(&head, 6);
    push(&head, 7);
    push(&head, 1);
    append(&head, 4);
    insertAfter(head->next, 8);
	deleteNode(&head, head->next);

    display(head);
    getchar();
    return 0;
}
```

This program allows us to have a front insertion, after node insertion, and end of list insertion. It also has the functionality to delete a specified node. The list can be traversed in normal and reverse direction. It contains all the basic operations executed in a doubly linked list. 

It's important to note that the deleteNode function will crash the program if you delete a node that does not exist. Always check if the node exists before deleting it.

