```python
# Importing necessary libraries
from datetime import datetime
from collections import defaultdict

class Book:
    def __init__(self, title, author, publication_year, isbn):
        self.title = title
        self.author = author
        self.publication_year = publication_year
        self.isbn = isbn
    def __repr__(self):
        return f"{self.title} by {self.author} ({self.publication_year})"

class Library:
    def __init__(self):
        self.catalog = defaultdict(list)

    def add_book(self, book):
        self.catalog[book.title] = book

    def remove_book(self, title):
        if title in self.catalog:
            del self.catalog[title]

class LibraryChain:
    def __init__(self):
        self.libraries = []

    def add_library(self, library):
        self.libraries.append(library)

    def remove_library(self, library):
        self.libraries.remove(library)

    def search_book(self, title):
        for library in self.libraries:
            if title in library.catalog:
                return library.catalog[title]
        return None

    def oldest_book(self):
        oldest_book = None
        for library in self.libraries:
            for book in library.catalog.values():
                if oldest_book is None or book.publication_year < oldest_book.publication_year:
                    oldest_book = book
        return oldest_book

    # List all books by a specific author
    def list_books_by_author(self, author):
        books = []
        for library in self.libraries:
            for book in library.catalog.values():
                if book.author == author:
                    books.append(book)
        return books

# Unit tests
def test_library_chain():
    book1 = Book('Title 1', 'Author 1', 2000, 'ISBN1')
    book2 = Book('Title 2', 'Author 2', 1990, 'ISBN2')
    book3 = Book('Title 3', 'Author 1', 2010, 'ISBN3')

    library1 = Library()
    library1.add_book(book1)

    library2 = Library()
    library2.add_book(book2)
    library2.add_book(book3)

    chain = LibraryChain()
    chain.add_library(library1)
    chain.add_library(library2)

    assert chain.search_book('Title 1') == book1
    assert chain.search_book('Title 2') == book2
    assert chain.search_book('Title 4') == None

    assert chain.oldest_book() == book2

    books_by_author1 = chain.list_books_by_author('Author 1')
    assert len(books_by_author1) == 2 and book1 in books_by_author1 and book3 in books_by_author1

    books_by_author2 = chain.list_books_by_author('Author 2')
    assert len(books_by_author2) == 1 and book2 in books_by_author2

if __name__ == "__main__":
    test_library_chain()
```

In this code, the class `Book` represents a book, the class `Library` represents a library with a catalog of books and the `LibraryChain` represents a chain of multiple libraries. Relevant methods for addition/removal of books and libraries, searching for a book, finding the oldest book and listing all books by a specific author have been defined in these classes. 

The function `test_library_chain()` in the end conducts some unit tests to verify the functionality of the code.

