<?php
function string_combinations($input_string, $index = -1, $res = '') {
    static $results = [];
    $num = strlen($input_string);

    for ($i = $index + 1; $i < $num; $i++) {
        $res .= $input_string[$i];
        $results[] = $res;
        string_combinations($input_string, $i, $res);
        $res = substr($res, 0, -1);
