  var text = document.getElementById("inputText").value;
  var formattedText = text.replace(/[^A-Za-z0-9]/g, '').toLowerCase();
  var reversedText = formattedText.split('').reverse().join('');
  if (formattedText == reversedText) {
    document.getElementById("output").innerHTML = "The text is a palindrome.";
  } else {
    document.getElementById("output").innerHTML = "The text is not a palindrome.";
  }
}
