```python
class Matrix3D:
    def __init__(self):
        self.data = {}

    def add_element(self, x, y, z, value):
        self._check_coords(x, y, z)

        if not isinstance(value, (int, float)):
            raise ValueError("Value should be a numeric type")

        if x not in self.data:
            self.data[x] = {}
        if y not in self.data[x]:
            self.data[x][y] = {}

        self.data[x][y][z] = value

    def remove_element(self, x, y, z):
        self._check_coords(x, y, z)

        try:
            del self.data[x][y][z]
            if not self.data[x][y]:
                del self.data[x][y]
            if not self.data[x]:
                del self.data[x]
        except KeyError:
            raise KeyError("No element at the given coordinates")

    def get_element(self, x, y, z):
        self._check_coords(x, y, z)

        try:
            return self.data[x][y][z]
        except KeyError:
            raise KeyError("No element at the given coordinates")

    def _check_coords(self, x, y, z):
        if not all(isinstance(i, int) for i in (x, y, z)):
            raise ValueError("All coordinates should be integers")
        if x < 0 or y < 0 or z < 0:
            raise ValueError("All coordinates should be non-negative")

# Testing the class

