matrix.add_element(0, 0, 0, 1)
matrix.add_element(1, 2, 3, 2)
print(matrix.get_element(0, 0, 0))  # output: 1
print(matrix.get_element(1, 2, 3))  # output: 2
matrix.remove_element(0, 0, 0)
