For this aggregation pipeline, we'll use the following stages:

1. `$match`: To select documents within a specific department.
2. `$group`: To group the documents by null (which groups all documents) and push the salary field to an array.
3. `$unwind`: To deconstruct the array of salaries.
4. `$sort`: To sort the salary field.
5. `$group`: To recalculate the array and calculate the indices for Q1, Q2 (median), Q3, and determining the IQR.
6. `$project`: To calculate the actual Q1, Q2, Q3 values and discard the outliers.
7. `$match`: To filter the salaries that are within the Q1 - 1.5xIQR and Q3 + 1.5xIQR range.
8. `$group`: To recalculate the array without the outliers.
9. `$project`: To calculate the median of the salaries considering an even set of salaries.

The JavaScript code using the MongoDB NodeJS Driver would look something like this:

```javascript
const MongoClient = require('mongodb').MongoClient;
const uri = "mongodb+srv://<user>:<password>@cluster0.mongodb.net/test?retryWrites=true&w=majority";

const client = new MongoClient(uri, { useNewUrlParser: true, useUnifiedTopology: true });
client.connect(err => {
  const collection = client.db("test").collection("employees");

  collection.aggregate([
    { 
      $match: { "department": "your_department" } 
    },
    {
      $group: {
        _id: null,
        salaries: { $push: "$salary" }
      }
    },
    {
      $unwind: "$salaries"
    },
    {
      $sort: { "salaries": 1 }
    },
    {
      $group: {
        _id: null,
        salaries: { $push: "$salaries" },
        count: { $sum: 1 }
      }
    },
    {
      $project: {
        Q1: { $arrayElemAt: ["$salaries", { $floor: { $multiply: ["$count", 0.25] } }] },
        Q3: { $arrayElemAt: ["$salaries", { $ceil: { $multiply: ["$count", 0.75] } }] },
        salaries: 1
      }
    },
    {
      $project: {
        lowerRange: { $subtract: ["$Q1", { $multiply: [{ $subtract: ["$Q3", "$Q1"] }, 1.5] }] },
        upperRange: { $add: ["$Q3", { $multiply: [{ $subtract: ["$Q3", "$Q1"] }, 1.5] }] },
        salaries: 1
      }
    },
    {
      $unwind: "$salaries"
    },
    {
      $match: {
        salaries: { $gte: "$lowerRange", $lte: "$upperRange" }
      }
    },
    {
      $group: {
        _id: null,
        salaries: { $push: "$salary" },
        count: { $sum: 1 }
      }
    },
    {
      $project: {
        median: {
          $cond: {
            if: { $mod: ["$count", 2] },
            then: { $arrayElemAt: ["$salaries", { $floor: { $divide: ["$count", 2] } }] },
            else: {
              $divide: [
                { $add: [
                  { $arrayElemAt: ["$salaries", { $subtract: [{ $divide: ["$count", 2] }, 1] }] },
                  { $arrayElemAt: ["$salaries", { $divide: ["$count", 2] }] }
                ]},
                2
              ]
            }
          }
        }
      }
    }
  ]).toArray((err, res) => {
    if (err) throw err;
    console.log(res);
  });

  client.close();
});
```

Please replace "your_department" with your desired department and correct MongoDB URI with username and password. The above example is for the Node.js MongoDB driver, different syntax might be needed for other drivers. Note that the accuracy of results might be affected by extreme values and this Aggregation does not scale well on large data sets.

