Here is a Python solution using classes and random to simulate the dice:

```python
import random

class Die:
    """
    Individual die class.
    Can change number of sides and roll itself.
    """
    def __init__(self, sides):
        self.sides = sides

    def roll(self):
        return random.randint(1, self.sides)

    def change_sides(self, new_sides):
        self.sides = new_sides

class Dice:
    """
    Multiple dice class.
    Can add new dice, roll all dice and get the sum, 
    or roll individual die.
    """
    def __init__(self):
        self.dice = []

    def add_die(self, sides):
        self.dice.append(Die(sides))

    def roll_all(self):
        return sum(die.roll() for die in self.dice)

    def roll_die(self, index):
        if index < 0 or index >= len(self.dice):
            return "Invalid index!"
        return self.dice[index].roll()

    def change_sides(self, index, new_sides):
        if index < 0 or index >= len(self.dice):
            return "Invalid index!"
        self.dice[index].change_sides(new_sides)
```
