Here's the simplest way to solve this task using a Javascript function. You could improve it as needed. It works by generating all possible substrings, storing them into a hashmap, and then finding the lengthiest repeatedly occurring substring.

```javascript
function longestRepeatedSubstring(s) {
    let map = new Map();
    let len = s.length;

    // Generate all substrings
    for(let i = 0; i < len; i++){
        for(let j = i+1; j <= len; j++){
            let sub = s.substring(i, j);
            if(map.has(sub)){
                map.set(sub, map.get(sub) + 1);
            }
            else {
                map.set(sub, 1);
            }
        }
    }

    let maxSub = "";
    let maxCount = 0;

    // Search for the substring with the greatest count that is not the full string
    for(let [key, value] of map){
        if(value > 1 && key.length > maxSub.length && key.length < len) {
            maxSub = key;
            maxCount = value;
        }
    }

    return maxSub == "" ? "No repeated substrings" : `Substring: ${maxSub}, Occurrence: ${maxCount}`;
}


