}

export function asyncCustomValidator(control: FormControl): Observable<ValidationErrors | null> {
  const { value } = control;
  // Here you can even call a service to validate the value asynchronously, for the demo we will check is value is 'async valid'
  // Replace this with your actual async validation logic
  return of(value === 'async valid').pipe(
