```python
class Node:
    def __init__(self, id, data):
        self.id = id
        self.data = data
        self.children = []
        self.parent = None

class Tree:
    def __init__(self):
        self.nodes = {}
        self.root = None

    def add_node(self, id, data, parent_id=None):
        node = Node(id, data)

        if self.root is None:
            self.root = node
        else:
            parent = self.nodes[parent_id]
            parent.children.append(node)
            node.parent = parent

        self.nodes[id] = node

def dfs(tree, node, goal, path):
    path.append(node.id)

    if node.id == goal:
        return path

    for child in node.children:
        result = dfs(tree, child, goal, list(path))

        if result is not None:
            return result

    return None

def find_shortest_path(tree, goal):
    return dfs(tree, tree.root, goal, [])

tree = Tree()
tree.add_node(1, "root")
tree.add_node(2, "child1", 1)
tree.add_node(3, "child2", 1)
tree.add_node(4, "child3", 2)

goal_id = 4
path = find_shortest_path(tree, goal_id)

if path is None:
    print(f"No path to node {goal_id}")
else:
    print(f"Shortest path from root to node {goal_id}: {path}")
```

In this code, each addition to the Tree adds a new Node with a specified parent, building the tree from the root up. Then we run a depth-first search on the tree to find the shortest path from the root to a particular goal node.

This DFS function returns the path from the root to that node as a list of node ids. If no path to the node exists, it returns None.

Finally, we print the result.  

