```python
def merge_unique_sorted(list1, list2):
    result = [] 
    i, j = 0, 0

    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            if len(result) == 0 or list1[i] != result[-1]: 
                result.append(list1[i])
            i += 1
        else:
            if len(result) == 0 or list2[j] != result[-1]: 
                result.append(list2[j])
            j += 1

    while i < len(list1): 
        if len(result) == 0 or list1[i] != result[-1]: 
            result.append(list1[i])
        i += 1

    while j < len(list2): 
        if len(result) == 0 or list2[j] != result[-1]: 
            result.append(list2[j])
        j += 1

    return result

```

