fn find_smallest_evens(numbers: Vec<i32>) -> (Option<i32>, Option<i32>) {
    let mut smallest = None;
    let mut second_smallest = None;

    for num in numbers {
        if num % 2 == 0 {
            if smallest.is_none() || num < smallest.unwrap() {
                second_smallest = smallest;
                smallest = Some(num);
            } else if second_smallest.is_none() || num < second_smallest.unwrap() && num != smallest.unwrap() {
                second_smallest = Some(num);
            }
        }
    }
