import cmath

def solve_quadratic(a, b, c):
    if a == 0:
        if b != 0:
            # The equation becomes a linear equation bx + c = 0 --> x = -c/b
            print('This is a linear equation. The root is {}'.format(-c / b))
        else:
            if c == 0:
                # This isn't meaningful as it stands for 0 = 0
                print("This is an identity.")
            else:
                # This stands for the absurd equation 0c = 0, with !c
                print("This is a contradiction.")
    else:
        # Calculate the discriminant
        d = (b**2) - (4*a*c)

        # Two solutions
        root1 = (-b-cmath.sqrt(d))/(2*a)
        root2 = (-b+cmath.sqrt(d))/(2*a)

        if d < 0:
            print("The equation has two complex roots: {} and {}".format(root1, root2))
        elif d == 0:
            print("The equation has one real root: {}".format(root1))
