void bubble_sort(std::vector<int>& arr)
{
    int n = arr.size();
    for(int i=0; i < n; ++i)
    {
        for(int j=0; j < n-i-1; ++j)
        {
            if(arr[j] > arr[j+1])
            {
                // Swap arr[j] and arr[j+1]
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

