Sure, Here's an implementation of a simple singly linked list data structure in C++:

```cpp
#include <iostream>

struct Node {
  int data;
  Node* next;
};

// Function to add node at the end of the list
void insertNode(Node** head, int newData) {
  Node* newNode = new Node();
  newNode->data = newData;
  newNode->next = NULL;

  if (*head == NULL) {
    *head = newNode;
    return;
  }

  Node* last = *head;
  while (last->next) {
    last = last->next;
  }

  last->next = newNode;
}

// Function to reverse the list
void reverseList(Node** head) {
  Node* prev = NULL;
  Node* current = *head;
  Node* next = NULL;

  while (current) {
    next = current->next;
    current->next = prev;
    prev = current;
    current = next;
  }

  *head = prev;
}

// Function to print the list
void printList(Node* head) {
  while (head) {
    std::cout << head->data << " ";
    head = head->next;
  }

  std::cout << "\n";
}

int main() {
  Node* head = NULL;

  insertNode(&head, 10);
  insertNode(&head, 20);
  insertNode(&head, 30);
  insertNode(&head, 40);

  std::cout << "Original list: ";
  printList(head);

  reverseList(&head);

  std::cout << "Reversed list: ";
  printList(head);

  return 0;
}
```

This program first creates a linked list with four nodes containing the values 10, 20, 30, and 40. It then prints out the list, reverses it and prints it out again. In the reversed list, the nodes are in the opposite order.

To compare complex numbers, we'll implement the math concept, where the magnitude (or modulus) of a complex number is used for comparison. The magnitude is obtained by computing the square root of the sum of squares of the real and imaginary parts, as follows:

magnitude = ||z|| = sqrt(a^2 + b^2), where a and b are the real and imaginary parts respectively

Here is the Java method that uses this concept:

```java
public class Main{
    static class Complex {
        double real, img;

        // A constructor to create a complex number
        Complex(String s) {
            String[] vals = s.trim().split("\\+");
            this.real = Double.valueOf(vals[0]);
            String imgString = vals[1];
            this.img = Double.valueOf(imgString.substring(0, imgString.length()-1));
        }

        // Function to calculate the magnitude of complex number
        double magnitude() {
            return Math.sqrt(Math.pow(this.real, 2) + Math.pow(this.img, 2));
        }
    }

    static String highestComplex(String a, String b, String c) {
        Complex comp1 = new Complex(a);
        Complex comp2 = new Complex(b);
        Complex comp3 = new Complex(c);

        if(comp1.magnitude() > comp2.magnitude() && comp1.magnitude() > comp3.magnitude()) 
            return a;
        else if(comp2.magnitude() > comp1.magnitude() && comp2.magnitude() > comp3.magnitude()) 
            return b;
        else 
            return c;
    }

    public static void main(String[] args) {
        String val1 = "9+7i";
        String val2 = "4+3i";
        String val3 = "8+1i";

        System.out.println("The highest complex number is: " + highestComplex(val1, val2, val3));
    }
}
```

In the code above, your complex numbers should be in the form "A+Bi". The Complex class constructor will parse the string into real and imaginary parts. The highestComplex method will then create Complex objects and compare their magnitudes. The complex number with the highest magnitude will be returned.

This code will print: "The highest complex number is: 9+7i".

