Here is a function in jQuery that adds a new table row at a specified index with any number of columns and their associated data.

```javascript
function addRow(data, index, tableId) {
  // Fetch the target table
  var table = $(`#${tableId}`);

  // Count existing columns
  var exColCount = $(table).find('tr')[0].cells.length;

  // Validate number of columns
  if (data.length != exColCount) {
    alert("Error: Number of data points does not match the number of existing columns. Specify the correct number of data points.");
    return;
  }

  // Create new row
  var newRow = $("<tr></tr>");

  // Add data to each column  
  data.forEach((item) => {
     var newCol = $("<td></td>").text(item);
     newRow.append(newCol);
  }); 

  // Append row to the specified index
  if(index == 0){
    $(table).prepend(newRow); // If index is 0, insert at the beginning
  } else {
    $(table).find('tr').eq(index - 1).after(newRow); // Else insert after nth Row
  }
}

addRow(["Data1", "Data2", "Data3"], 1, "exampleTableId");
