首先，建立一個JavaScript函數，然後分別對兩個字串應用氣泡排序算法。氣泡排序算法是一種簡單的排序算法，它不斷的遍歷列表，比較每對相鄰元素。如果他們的順序錯誤就將他們交換過來，直到列表排序完成。這樣，對於字串1，我們預期得到" dehllloorw"（以字母順序），對於字串2，我們預期得到"ttssropmmgniraep"（以字母的反序列）。

在下面的JavaScript代碼片段中，我創建了一個名為bubbleSort的函數，該函數接受兩個參數（需要排序的兩個字串）並返回它們的排序版本。字串1和字串2是一樣的排序，但字串2在返回時被反轉了。

```javascript
function bubbleSort(string1, string2) {
    var array1 = string1.split('');
    var array2 = string2.split('');

    for (var i = 0; i < array1.length; i++) {
        for (var j = i + 1; j < array1.length; j++) {
            if (array1[i] > array1[j]) {
                var temp = array1[i];
                array1[i] = array1[j];
                array1[j] = temp;
            }
        }
    }

    for (var i = 0; i < array2.length; i++) {
        for (var j = i + 1; j < array2.length; j++) {
            if (array2[i] > array2[j]) {
                var temp = array2[i];
                array2[i] = array2[j];
                array2[j] = temp;
            }
        }
    }

    return {
        string1: array1.join(''),
        string2: array2.reverse().join('')
    };
}

console.log(bubbleSort('hello world', 'programming test'));
