class StringDictionary:
    def __init__(self):
        self.dictionary = {}

    def add_string(self, string):
        for char in string:
            char = char.lower()
            if char in self.dictionary:
                self.dictionary[char] += 1
            else:
                self.dictionary[char] = 1
        self.dictionary = dict(sorted(self.dictionary.items(), key=lambda item: item[1], reverse=True))

    def remove_string(self, string):
        for char in string:
            char = char.lower()
            if char in self.dictionary:
                self.dictionary[char] -= 1
                if self.dictionary[char] == 0:
                    del self.dictionary[char]
        self.dictionary = dict(sorted(self.dictionary.items(), key=lambda item: item[1], reverse=True))

    def search_key(self, key):
        key = key.lower()
        return self.dictionary.get(key, 'Key not found')

    def print_dictionary(self):
        for key, value in self.dictionary.items():
            print(f"Character: '{key}'\tCount: {value}")

string_dict = StringDictionary()
strings = ['Google@2021', 'Microsoft!!!', 'Apple Inc. 1976#']

for string in strings:
    string_dict.add_string(string)

print("Initial Dictionary")
