import java.util.*

fun main(args: Array<String>) {

    val reader = Scanner(System.`in`)
    print("Enter two numbers: ")

    val num1 = reader.nextDouble()
    val num2 = reader.nextDouble()

    print("Enter an operator (+, -, *, /): ")
