#include<stdio.h>

#define SIZE 3

// Function for adding two polynomials
void add(int poly1[], int poly2[], int size) {
   int sum[size];
   for (int i=0; i<size; i++)  
       sum[i] = poly1[i] + poly2[i];
   printf("Sum of Polynomials is: ");
   for (int i=0; i<size; i++) {
      printf("%d", sum[i]);
      if (i != 0) 
        printf("x^%d", i);
      if (i != size-1)
      printf(" + ");
   }
}

// Function for subtracting two polynomials
void subtract(int poly1[], int poly2[], int size) {
   int diff[size];
   for (int i=0; i<size; i++)  
       diff[i] = poly1[i] - poly2[i];
   printf("\nDifference of Polynomials is: ");
   for (int i=0; i<size; i++) {
      printf("%d", diff[i]);
      if (i != 0) 
        printf("x^%d", i);
      if (i != size-1)
      printf(" - ");
   }
}

// Function for multiply two polynomials
void multiply(int poly1[], int poly2[], int size) {
   int prod[2*size - 1];
   for (int i = 0; i<2*size-1; i++)  
       prod[i] = 0;
   for (int i=0; i<size; i++)  
    for (int j=0; j<size; j++)
       prod[i+j] += poly1[i]*poly2[j]; 
   printf("\nProduct of Polynomials is: ");
   for (int i=0; i<2*size-1; i++) {
      printf("%d", prod[i]);
      if (i != 0) 
        printf("x^%d", i);
      if (i != 2*size-2)
      printf(" + ");  
   }
}

int main() {
   int poly1[SIZE] = {5, 0, 10, 6};
   int poly2[SIZE] = {1, 2, 4};

   add(poly1, poly2, SIZE);
   subtract(poly1, poly2, SIZE);
   multiply(poly1, poly2, SIZE);

   return 0;
}
