                if string[i-1] not in result[char]['preceding']:
                    result[char]['preceding'][string[i-1]] = 1
                else:
                    result[char]['preceding'][string[i-1]] += 1

            if i == len(string) - 1:
                # If char is at the end of the string
                if None not in result[char]['succeeding']:
                    result[char]['succeeding'][None] = 1
                else:
                    result[char]['succeeding'][None] += 1

