Here's a simple way to approach it in C++. Note that this will involve using dynamic 2D arrays, and creating a matrix class / constructor is out of scope.

```cpp
#include<iostream>
using namespace std;

int main() {
    // Define matrix dimensions
    int rows = 3;
    int columns = 3;

    // Generate dynamic 2D matrix
    int **matrix = new int*[rows];
    for(int i = 0; i < rows; i++)
        matrix[i] = new int[columns];

    // Initialize matrix elements
    int count = 1;
    for(int i=0; i<rows; i++)
        for(int j=0; j<columns; j++)
            matrix[i][j] = count++;

    // Transpose the matrix
    int **transpose = new int*[columns];
    for(int i = 0; i < columns; i++)
        transpose[i] = new int[rows];

    for(int i=0; i<columns; i++)
        for(int j=0; j<rows; j++)
            transpose[i][j] = matrix[j][i];

    // Print transpose of matrix
    cout << "Transpose of the Matrix: " << endl;
    for(int i=0; i<columns; i++) {
        for(int j=0;j<rows;j++)
            cout << transpose[i][j] << " ";
        cout << "\n";
    }

    // Release dynamically allocated memory
    for(int i = 0; i < rows; i++)
        delete [] matrix[i];
    delete [] matrix;

    for(int i = 0; i < columns; i++)
        delete [] transpose[i];
    delete [] transpose;

    return 0;
}
```

In this program, we first define the dimensions of the matrix and allocate memory for it. Then, we initialize the elements of the matrix, calculate its transpose, and print the transposed matrix. Finally, we free the dynamically allocated memory. The matrix and the transpose matrix both use dynamically allocated 2D arrays.

Here is a solution showing how to implement a thread-safe Hashmap and functionality for managing customer transactions in Java. Note that this is a simplified example and real-world applications may need more complex error handling and business rules.

```java
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class HashMapExample {

    public static class Transaction {
        private Double amount;
        private LocalDate date;
        private String type;

        // getters and setters
    }

    public static class CustomerTransactions {
        private ConcurrentHashMap<String, List<Transaction>> customerTransactions = new ConcurrentHashMap<>();

        public List<Transaction> fetchTransactions(String email) {
            return customerTransactions.get(email).stream()
                .sorted(Comparator.comparing(Transaction::getDate).reversed())
                .collect(Collectors.toList());
        }

        public void addTransaction(String email, Transaction transaction) {
            customerTransactions.compute(email, (key, transactions) -> {
                if (transactions == null) {
                    transactions = new ArrayList<>();
                }
                transactions.add(transaction);
                return transactions;
            });
        }

        public double getTotalTransactionValue(String email) {
            return customerTransactions.get(email).stream()
                .mapToDouble(Transaction::getAmount)
                .sum();
        }

        public String getMostFrequentTransactionType(String email) {
            return customerTransactions.get(email).stream()
                .collect(Collectors.groupingBy(Transaction::getType, Collectors.counting()))
                .entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey)
                .orElse(null);
        }
    }
}
```

