function getLeastCommonProperty(obj) {
    var count = {};
    var leastCommon = null;
    var minCount = Infinity;

    // Count the occurrence of each property
    for (var prop in obj) {
        if (obj.hasOwnProperty(prop)) { // to check if the property belongs to that object and not to its prototype chain
            if (count[obj[prop]]) {
                count[obj[prop]]++;
            } else {
                count[obj[prop]] = 1;
            }
        }
    }

    // Loop through the count object to find the property with minimum occurrence
    for (var prop in count) {
        if (count.hasOwnProperty(prop)) {
            if (count[prop] < minCount) {
                minCount = count[prop];
                leastCommon = prop;
            }
        }
    }

    return leastCommon;
