Here is a C++ program that creates a binary search tree (BST) and conducts a level-order (breadth-first) traversal.

```cpp
#include<bits/stdc++.h>
using namespace std;

// definition of a node in the tree
struct Node
{
    int data;
    struct Node* left, * right;
};

// function that allocates a new node with the given data and NULL left and right pointers.
struct Node* newNode(int data)
{
    struct Node* node = new Node;
    node->data = data;
    node->left = node->right = NULL;
    return(node);
}

// function to print level order traversal of tree
void printLevelOrder(Node *root)
{
    if (root == NULL) return;
    queue<Node *> q;
    q.push(root);

    while (q.empty() == false)
    {
        Node *node = q.front();
        cout << node->data << " ";
        q.pop();
        if (node->left != NULL)
            q.push(node->left);
        if (node->right != NULL)
            q.push(node->right);
    }
}

// function to insert a new node with given key in BST
struct Node* insert(struct Node* node, int data)
{
    // if the tree is empty, assign a new node address
    if (node == NULL) return(newNode(data));

    // else recur down the tree
    if (data < node->data)
        node->left = insert(node->left, data);
    else if (data > node->data)
        node->right = insert(node->right, data);

    // return the (unchanged) node pointer
    return node;
}

// main function
int main()
{
    struct Node *root = NULL;
    root = insert(root, 50);
    insert(root, 20);
    insert(root, 10);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);

    cout << "Level order traversal of the given binary search tree is: ";
    printLevelOrder(root);

    return 0;
}
```

In this program, a new node is created with `newNode()`, inserted with `insert()`, and level order traversal is done using `printLevelOrder()`. The `printLevelOrder()` function prints every level of the tree from the root downwards, left to right, as per the definition of level order traversal. It uses a queue to achieve this.

