```python
def is_anagram_recursive(word):
    # Base case: if the word has length 0 or 1, it's an anagram of itself.
    if len(word) == 0 or len(word) == 1:
        return True

    # Recursive case: if the first and last characters are equal, remove them and continue checking the next characters.
    if word[0] == word[-1]:
        return is_anagram_recursive(word[1:-1])
    else:
        return False


# Testing the is_anagram_recursive function with some examples.
