TOKEN = "YOUR_GITHUB_TOKEN"
HEADERS = {"Authorization": f"Bearer {TOKEN}"}
QUERY = """
{
  repository(owner: "ruby", name: "ruby") {
    releases(last: 1) {
      nodes {
        name
        tag {
          name
        }
        description
      }
    }
  }
}
"""

def get_release_details():
    try:
        response = requests.post(API, json={'query': QUERY}, headers=HEADERS)
        response.raise_for_status()

    except requests.exceptions.RequestException as err:
        print(f"Request error: {err}")
        return None

    else:
        result = response.json()
        release_info = result["data"]["repository"]["releases"]["nodes"][0]
        return release_info


def write_to_db(data):
    con = sqlite3.connect('ruby_releases.db')
    cur = con.cursor()

    cur.execute('''
        CREATE TABLE IF NOT EXISTS releases
        (name TEXT PRIMARY KEY, tag_name TEXT, description TEXT)
    ''')

    try:
        cur.execute('''
            INSERT INTO releases (name, tag_name, description)
            VALUES (?, ?, ?)
        ''', (data["name"], data["tag"]["name"], data["description"]))
    except sqlite3.IntegrityError:
        print("Data already exists in the database")
        return False
    else:
        con.commit()
        con.close()
        return True


def main():
    release_details = get_release_details()

    if release_details is not None:
        write_to_db(release_details)


class TestMethods(unittest.TestCase):

    def setUp(self):
        self.test_data = {"name": "v2.7.2", "tag": {"name": "v2_7_2"}, "description": "This is a TEST"}

    def test_get_release_details(self):
        self.assertIsNone(get_release_details())

    def test_write_to_db(self):
        self.assertTrue(write_to_db(self.test_data))


if __name__ == "__main__":
    main()
    unittest.main()
```

