Here's a C++ implementation that uses the concept of dynamic programming to solve this problem. The `findOverlappingSubstrings` function takes two UTF-8 strings as input and finds the longest common substrings, taking into account overlapping cases. We use vectors for efficient access and modification of data. To properly handle literal UTF-8 strings, be sure to save the source code file as UTF-8.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

vector<string> findOverlappingSubstrings(string s1, string s2) {
    int len1 = s1.size();
    int len2 = s2.size();
    int maxLen = 0;
    vector<vector<int>> dp(len1 + 1, vector<int>(len2 + 1, 0));
    vector<string> result;

    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;

                if (dp[i][j] > maxLen) {
                    maxLen = dp[i][j];
                    // clear the result vector to store new longest substring
                    result.clear();
                    result.push_back(s1.substr(i - maxLen, maxLen));
                } 
                else if (dp[i][j] == maxLen) {
                    // to handle overlapping cases, if we get an equal length substring, we push it into result
                    result.push_back(s1.substr(i - maxLen, maxLen));
                }
            }
        }
    }
    return result;
}

int main() {
    string str1 = "abcabcd";
    string str2 = "abcdabc";
    vector<string> commonSubStrs = findOverlappingSubstrings(str1, str2);

    for (string s : commonSubStrs) {
        cout << s << endl;
    }

    return 0;
}
```

Note that this solution assumes the strings are valid UTF-8 and contain only characters that share the same representation in ASCII for the sake of simplicity. Full UTF-8 support would require a custom comparison function that decodes multibyte characters from both strings before comparing them, which is beyond the scope of this question.

