```java
public class Main {
    public static void main(String[] args) {
        int [] numbers = {1, 5, 10, 20};
        System.out.println(findDifference(numbers));
    }

    public static int findDifference(int[] numbers){
        if(numbers==null || numbers.length==0)
            return 0;
        int max = numbers[0];
        int min = numbers[0];
        for(int i=0;i<numbers.length;i++){
            if(numbers[i]>max)
                max = numbers[i];
            if(numbers[i]<min)
                min = numbers[i];
        }
        return max-min;
    }
}
```

