```javascript
var inventory = [
    { name: 'Apple', cost: 10 },
    { name: 'Banana', cost: 15 },
    { name: 'Cherry', cost: 20 },
    { name: 'Date', cost: 12 },
    { name: 'Elderberry', cost: 25 }
];

